      },
      "background": {
        "environment": "open_air_twilight_sky_with_soft_clouds",
        "bokeh": "soft_background_blur_no_hard_edges"
      }
    },
    "scene": {
      "global_description": "一对电影写实风格的 Cosplay 情侣，置身于黄昏时分充满希腊神话气息的场景中。男子身材高大健硕，肤色温暖黝黑，短卷赤褐色头发，下颌线条分明。他身穿棕色皮革英雄盔甲，带有精致的浮雕漩涡图案，一件蓝色斗篷披在一侧肩上，佩戴简约的臂甲。女子身材纤细，肤色介于白皙与橄榄色之间，眼神富有表现力，深棕色长发扎成高耸蓬松的马尾。她身穿无袖淡紫色连衣裙，紧身胸衣搭配柔和垂坠的裙摆。他们的互动温柔而真实，面部结构自然，布料张力逼真，手部姿势轻柔。无风格化，无动画感。",
      "shots": [
        {
          "shot_id": "PANEL_01",
          "framing": "medium_close_up",
          "action": "他们倾身轻柔亲吻。男子双眼紧闭，女子脸部向上微仰。她的左手轻柔地搭在他的上臂，他的右手扶着她的腰部。亲密而雅致。",
          "expression": "平静、深情、真诚",
          "micro_details": "微妙的唇部接触真实感，自然的睫毛阴影，淡淡的皮肤光泽，淡紫色连衣裙上逼真的布料褶皱，斗篷布料的重量感可见"
        },
        {
          "shot_id": "PANEL_02",
          "framing": "medium_shot"
        }
      ]
    }
  }
}

