    },
    "facial_features": {
      "eyes": "浅蓝绿色虹膜，杏仁状。妆容特点是上眼睑有清晰、锐利的黑色飞翼眼线（猫眼风格），睫毛分明。",
      "eyebrows": "修剪整齐，弓形，浅棕色，自然浓密。",
      "nose": "小巧的纽扣鼻，鼻尖略微上翘。",
      "lips": "丰满的嘴唇，自然的玫瑰粉色，微微张开，呈柔和的嘟嘴状。",
      "cheeks": "高颧骨，带有柔和的桃色/古铜色腮红修容。",
      "expression": "妩媚、自信，与倒影直接眼神交流，略带诱惑的镜子自拍凝视。"
    },
    "apparel": {
      "headwear": "迷彩印花（绿/棕/米色）棒球帽，帽前板绣有粉色玫瑰花图案。",
      "top": "白色华夫格（保暖纹理）无袖露脐上衣。领口和袖窿处有浅青色/淡蓝色罗纹边饰。露出腰部。",
      "bottoms": "紧身、低腰的亮粉色打底裤/瑜伽裤。面料看起来柔软有弹性，紧贴身形。",
      "accessories": "粗大的金色链条项链（项圈款式）。长指甲，涂有浅色/白色指甲油。"
    },
    "pose_and_action": {
      "stance": "侧身站立，背对镜子，扭动躯干回头看向倒影。重心转移以突出曲线。",
      "hands": "右手举着智能手机，捕捉镜子自拍。手指牢牢握住手机。",
      "device": "iPhone，配有亮橙色保护壳，背面有一个圆形 MagSafe 环。"
    },
    "environment_and_background": {
      "setting": "家用浴室内部。",
      "lighting": "明亮的人工室内顶灯。帽檐在额头投下阴影。",
      "objects_visible": {
        "door": "左侧可见白色镶板内门。",
        "wall_decor": "右侧墙壁上有裱框的艺术品。其中一个画框内是一幅白色海扇/珊瑚在海军蓝背景上的版画，配有浅色木质画框。",
        "fixtures": "底部边缘可见白色陶瓷浴室水槽。部分可见镀铬水龙头把手。",
        "mirror_details": "图像是倒影。镜面并非完美清洁；玻璃下半部分有可见的白色水渍、污迹和牙膏飞溅，增加了真实感。"
      },
      "colors": "调色板以裤子的亮粉色、手机壳的橙色、上衣的白色/蓝色和中性色为主。"
    }
  }
}

