          "hair": "蓬松、长长的浅金色头发，造型为柔和、垂坠的波浪，环绕着她的脸庞。",
          "eyes": "引人注目的清澈蓝色眼睛，看向镜头。",
          "skin": "白皙的肤色，散发着自然的光泽。"
        },
        "expression_and_mood": "温柔、放松、自然的表情，带着一丝微笑。"
      },
      "clothing_and_accessories": {
        "main_outfit": {
          "garment_type": "迷你连衣裙",
          "color_pattern": "以浓郁的 {argument name=\"dress color\" default=\"蓝色\"} 为底色，上面是精致的复古花卉图案，色调为浅蓝色和泥土棕色。",
          "design_features": [
            "醒目的泡泡袖",
            "合身、紧密褶皱的紧身胸衣，增添了质感",
