          ],
          "fabric_texture": "柔软的棉府绸外观。"
        },
        "footwear": {
          "type": "过膝靴",
          "material": "丰富的棕色麂皮，质地柔软，略带松垮感。",
          "details": "平底或低跟，做旧外观。"
        },
        "jewelry": {
          "earrings": "闪闪发光的金色垂坠耳环，在日光下熠熠生辉。",
          "necklace": "一条精致的细银链项链，上面有一个小巧、朴素的圆盘吊坠，垂落在她的锁骨附近。"
        }
      },
      "action_and_pose": {
        "posture": "放松地坐着。",
        "positioning": "双腿舒适地交叉在膝盖处。双手轻轻地放在木凳粗糙的表面上。",
        "orientation": "身体略微倾斜，面向前方。"
      }
    },
    "environmental_context": {
      "immediate_surroundings": {
        "seating": "一张乡村风格的、饱经风霜的木凳，显示出岁月的痕迹、剥落的油漆和粗糙的纹理。",
        "structures": "一堵乡村风格的小木屋外墙构成了近景背景，墙壁由巨大的、粗糙的木材原木构成，可见其间的填缝砂浆。"
      },
      "distant_landscape": {
        "geography": "远方绵延的山脉。",
        "terrain": "干枯的金黄色草地一直延伸到山脉。",
        "sky": "戏剧性的天空，布满了厚重的、漫射的灰色和白色云朵。"
      },
      "atmosphere_and_time": "清爽的秋日氛围。"
    },
    "photographic_execution": {
      "technical_specs": {
        "resolution": "4K 超高清",
        "aspect_ratio": "9:16 (垂直肖像)",
        "overall_quality": "超细节、画报级的照片质量，具有令人难以置信的清晰度。"
      },
      "lighting_setup": {
        "type": "自然日光。",
        "quality": "柔和、漫射、均匀的光线（阴天），消除了刺眼的阴影和高光。"
      }
    }
  }
]

