{
  "image_generation_prompt": {
    "subject_details": {
      "appearance": "年轻女性，留着蓬松浓密、金金色波浪长发，有明显的飞发和自然卷曲。肤色苍白，带有清晰、未经修饰的纹理（毛孔、淡淡的雀斑、汗毛）。表情沉思而平静。目光锐利，直视镜头，眼神中有清晰的眼神光。",
      "pose": "随意、非摆拍地坐在红色扶手椅上。一条腿弯曲，膝盖抵住胸部，另一条腿向下伸展。身体前倾，右肘放在膝盖上，手轻微挤压脸颊。左臂随意搭在抬起的腿上。"
    },
    "outfit_and_attire": {
      "upper_body": "紧身浅蓝色罗纹背心，可见织物纹理，外面套着一件超大号米色纽扣衬衫。衬衫未扣，滑落肩膀，有明显的褶皱和缝线细节。",
      "lower_body": "浅色水洗蓝色牛仔裤，重度磨损，膝盖处有大的真实破洞，裤脚磨损，有松散的线头。",
      "footwear": "脏旧的白色高帮帆布运动鞋（匡威风格），橡胶鞋头磨损，鞋带系得不均匀。",
      "accessories": "叠戴的厚重戒指，镶嵌绿松石和琥珀石；彩色不规则串珠手链（右手腕）；细银链（左手腕）；精致项链在光线下闪烁。"
    },
    "environment_and_setting": {
      "furniture": "复古 {argument name=\"furniture type\" default=\"红色皮革俱乐部扶手椅\"}，皮革纹理开裂，缝隙中有灰尘，坐垫下陷，显示出重量感。",
      "props": "杂乱的室内。左侧有一个风化的蓝色金属置物架，上面堆满了翻旧的书籍和光面杂志。椅子扶手上散落着纸张。真实的房间杂乱感。",
      "background": "深青蓝色墙壁，油漆剥落或有纹理。背景虚化的艺术版画。右侧有半透明的粉色窗帘，捕捉着环境光。",
      "floor": "深色木地板，有磨损痕迹，在光线下可见细小的碎屑/灰尘颗粒。"
    },
    "technical_specifications": {
      "camera_gear": "使用 35mm 胶片拍摄，柯达 Portra 400 胶卷，徕卡 M6 相机搭配 35mm Summilux 镜头。",
      "lighting": "自然窗户光和直射相机闪光灯的混合。主体背后有硬阴影，额头和鼻梁上有高光。",
      "style": "原始街头摄影，90 年代杂志风格，闪光灯摄影，未经修饰，真实的业余美学。",
      "post_processing": "胶片颗粒，轻微色差，高对比度，鲜艳饱和度，轻微暗角，RAW 照片文件。"
