promptCh:
{
  "subject": {
    "description": "一张坦率、超真实的镜面自拍照片，画面中一位金发年轻女子身材极具吸引力，站在卧室里。",
    "body": {
      "physique": "她拥有健身模特般高度发达、丰腴的体格，曲线极致。她的臀部非常宽，臀大肌（glutes）发育得非常饱满，极其硕大、肌肉发达、圆润且突出，高耸紧致。她的胸部非常丰满、挺拔、坚挺，呈现上扬的轮廓。她的腰部非常纤细，呈锥形，营造出夸张的沙漏形身材。她的腿部和背部显示出健身训练的痕迹。她的皮肤被阳光亲吻过，带有明显的晒痕。",
      "pose": "她以侧后方姿势站立，扭转躯干，自信而诱惑地回望镜中的自己。她的重心转移，以最大限度地展现她的臀大肌和臀部。她左手拿着智能手机，右手放在臀部。",
      "face": "她的脸庞极具吸引力，美丽动人，五官迷人，散发着自然的光泽。她的皮肤完美无瑕，健康光滑，展现出真实的皮肤纹理，没有瑕疵。她带着自信、略带俏皮的微笑。",
      "features": "{argument name=\"features\" default=\"长金发，健身模特体格，高度发达的曲线。\"}"
    }
  },
  "wardrobe": {
    "outfit": "她穿着一套时尚、现代的细绳比基尼，设计符合当前流行趋势。面料是光滑的罗纹黑色材质，带有精致的金色金属五金细节。下装是高开叉、侧系带的丁字裤款式，高高地挂在她的臀部，突显她硕大、紧致的臀大肌。上装是极简的三角形剪裁，细肩带支撑并凸显她非常丰满、坚挺的胸部。"
  },
  "pose_action": "以侧面姿势拍摄站立镜面自拍，以突出她极致的健身体格。",
  "scene": {
    "environment": "一间明亮、居家但明显杂乱的卧室。",
    "elements": "镜子反射出凌乱的白色床铺，上面随意搭着衣服，一扇窗户挂着白色窗帘，透进明亮的日光，一个木制梳妆台，抽屉开着，物品散落一地。地板上散落着衣服和包。房间给人一种生活气息浓厚但杂乱的感觉。",
    "composition": "垂直 9:16 镜面自拍。构图捕捉了她从膝盖以上全身，重点突出极致的侧面曲线和杂乱的背景。"
  },
  "lighting": {
    "setup": "明亮、自然的日光从她身后的窗户射入。",
    "details": "光线环绕着她的曲线，突显肌肉线条和皮肤纹理。"
  },
  "camera": {
    "technical": "高质量智能手机自拍摄影。主体对焦锐利。超真实的皮肤纹理。图像必须捕捉所描述的精确健身模特比例。",
    "aspect_ratio": "9:16",
    "constraints": []
  }
}

