promptCh:
{
  "subject": {
    "description": "一位年轻的成年女性，留着长长的铂金色直发，发根颜色较深。她拥有深古铜色的肤色和丰满、曲线玲珑的身材，胸部非常突出，臀部宽大。她穿着一件黑色三角比基尼上衣，胸部几乎无法完全容纳，露出了明显的乳沟和胸部曲线。她穿着配套的黑色比基尼下装，高腰设计（丁字裤款式）。她的右下腹/骨盆区域有一个明显的纹身。",
    "anatomy": "丰满的沙漏型身材。胸部丰满下垂，具有自然的重力感，柔软的组织被手臂和比基尼上衣挤压。大腿粗壮柔软，平放在床上。面部特征包括咬东西时鼻子皱起的表情、轮廓分明的下颌线和修剪整齐的眉毛。",
    "clothing": "{argument name=\"bikini color\" default=\"Black\"} 绳索比基尼套装。上衣是简单的三角剪裁，配有细肩带。下装非常暴露，高高地挂在髋骨上。"
  },
  "pose": {
    "posture": "盘腿（裁缝式）坐在床上。躯干稍微朝镜子方向倾斜。她的体重深深地陷在柔软的床垫中。",
    "arms_and_hands": "右臂抬起，手拿着一大片 {argument name=\"food item\" default=\"cheese pizza\"} 直接送到嘴边，正在大口咬着。左臂向前伸出，拿着一部智能手机（贴有贴纸的 iPhone 手机壳）拍摄镜子自拍。",
    "head": "头部略微倾斜，眼睛看着手机屏幕/镜子反射。脸部被披萨片部分遮挡。",
    "action": "同时吃披萨和拍摄镜子自拍。"
  },
  "environment": {
    "setting": "酒店房间或卧室，夜晚。",
    "foreground": "一张铺着白色床单的床，床单有纹理和绗缝。床上散落着：一个打开的纸板披萨盒，上面有油渍和“OPEN 24 HOURS”字样（由于镜面反射，显示为反向的“SRUOH 42 NEPO”），一罐白色的“White Claw”硬苏打水，一个装有甜点（提拉米苏或蛋糕）和塑料勺的透明塑料容器，以及一个棕色奢侈手提包（路易威登 Monogram 图案）。",
    "background": "一扇通往黑暗阳台的推拉玻璃门。右侧挂着白色垂直窗帘。左侧可见一盏带白色灯罩的床头灯。",
    "context": "酒店房间内随意的深夜小吃场景。"
  },
  "camera": {
    "type": "镜子自拍。",
    "perspective": "通过镜子反射的视角。相机（手机）在主体左手中可见。",
    "framing": "中景拍摄，捕捉主体从胫骨以上到头部上方，包括周围的床铺空间。",
    "focal_length": "24mm 至 28mm（智能手机广角镜头等效）。",
    "depth_of_field": "景深较深，使床上的主体和背景元素都相对清晰。"
  },
  "lighting": {
    "source": "室内人工照明，可能是头顶的暖色钨丝灯与左侧台灯的光线混合。",
    "quality": "柔和但有方向性，营造出阴影"
  }

