promptEn:
{
  "vibe_title_en": "Organic Golden Alchemy",
  "master_prompt": "A hyper-realistic cinematic close-up of The Protagonist in a side-profile view, looking upward with a longing gaze, set inside a chaotic and sun-drenched Saffron Preservation Atelier. The environment is extremely busy and cluttered (Busy Environment Mode), filled with floor-to-ceiling shelves stacked with amber glass jars, bundles of dried yellow herbs, crumbling botanical encyclopedias, and scattered golden petals. The Protagonist wears a heavy, textured wool trench coat in mustard yellow that surrealistically morphs into a living collar of blooming marigolds, mimosa flowers, and crystallized honeycomb structures (Photographic Surrealism). The lighting is directional and warm, mimicking a &#x27;golden hour&#x27; shaft of light that highlights microscopic skin pores, dusting of yellow pollen on the cheeks, and the fibrous texture of the coat. Shot on a Hasselblad H6D-100c with an 80mm f/2.8 lens to create a shallow depth of field that blurs the dense background clutter while keeping the eye and floral textures razor-sharp. Kodak Portra 400 film stock emulation, fine grain, organic warmth, tactile atmosphere.",
  "meta": {
    "intent": "Editorial Fashion x Surrealism",
    "priorities": "Texture, Monochromatic Color, Busy Background, Photorealism",
    "device_profile": "High-End Desktop / Large Format Print"
  },
  "frame": {
    "aspect": "4:5",
    "composition": "Rule of Thirds, Side Profile",
    "layout": "Subject dominated foreground, dense background",
    "camera_angle": "Eye-level, slightly tilted upwards",
    "tilt_roll_degrees": "0"
  },
  "subject": {
    "gender": "Female",
    "identity": "The Protagonist (Universal Template)",
    "demographics": "Adult, Age-Neutral",
    "face": "Neutral expression, slight parting of lips, gazing upward",
    "hair": "Pulled back, integrated with surreal floral elements",
    "body": "Shoulders and head visible (Bust shot)",
    "expression": "Dreamy, longing, focused on a distant point",
    "pose": "Leaning slightly back, chin lifted, side profile"
  },
  "wardrobe_accessories": {
    "garments": [
      {
        "item": "Trench Coat",
        "material": "Heavy Wool / Felt",
        "color": "Mustard Yellow / Ochre",
        "fit": "Oversized, Structured"
      }
    ],
