  "hard_coded_scene_prompt": {
    "environment": "盛开野花田（{argument name=\"flowers\" default=\"紫色羽扇豆, 红色罂粟花, 雏菊\"}）, 模糊的自然背景, 户外草地, 鲜艳而柔和的自然色彩",
    "lighting": "强烈逆光（太阳在主体后方）, 镜头光晕, 头发边缘光, 柔和朦胧的氛围, 黄金时段或傍晚阳光",
    "composition": "中景（齐腰）, 视平线, 主体居中于花丛中, 景深效果, 前景花朵模糊"
  },
  "pipeline_sequence": {
    "_hint": "顺序：1. 读取并锁定角色（直接）-> 2. 从文本生成场景和姿势。",
    "step_1_character_reference_lock": {
      "action": "controlnet_reference_only",
      "target": "source_image_character",
      "purpose": "直接使用上传图片锁定面部结构和身份，不先修改源像素。",
      "weight": 0.85,
      "style_fidelity": 1
    },
    "step_2_final_synthesis": {
      "action": "generate_image",
      "prompt_construction": {
        "scene_text": "[hard_coded_scene_prompt]",
        "character_logic": "站在花田中。以柔和、梦幻的表情直视镜头。头发为白色/铂金色，凌乱、蓬松、被风吹拂，点缀着小树枝和野花。手臂自然垂于两侧。",
        "clothing_text": "奇幻自然风格的束身衣或连衣裙。由米色/棕褐色粗糙纹理面料（亚麻或粗麻布）制成。胸衣上装饰有真实的盛开野花（蓝色、红色、黄色）和藤蔓。原始下摆，有机外观。",
        "quality_text": "[quality_tags]"
      },
      "denoising_strength": 1,
      "instruction": "使用 &#x27;source_image_c&#x27; 生成图像"
    }
  }
}

