      "scene_summary": "穆拉，阿克亚卡-戈科瓦湾。一对年轻情侣在一个安静的小海湾晒太阳。男子在前景的毛巾上躺着，女子在中景的毛巾上坐着，两人都放松而快乐。他们身后是松树覆盖的岩石峭壁，海水清澈碧绿。抓拍，非摆拍，就像朋友拍的照片。",
      "subjects": {
        "count": 2,
        "description": "一对二十出头的年轻男女，普通真实，非模特身材；自然的身体和比例",
        "expression": "放松，快乐，淡淡的微笑；随意的眼神交流",
        "skin_and_face": "自然的皮肤纹理，逼真的毛孔，无美颜修饰，无塑料感皮肤"
      },
      "wardrobe_and_style": {
        "female": "简单的三角比基尼，暖色调 {argument name=\"bikini color\" default=\"珊瑚色/橙色\"}，太阳镜，极少/无首饰，头发因海风自然凌乱",
        "male": "简单的深色泳裤，无标志，放松的姿势",
        "rules": "仅限 PG-13 海滩装，自然非暴露"
      },
      "micro_action": "他们在晒太阳；男子稍微转向她；她坐着，双手撑在身后，微笑着；一个平静、温暖、充满人情味的时刻",
      "environment_details": {
        "location": "{argument name=\"location\" default=\"阿克亚卡-戈科瓦岩石海湾，穆拉\"}",
        "background": "巨大的浅色岩石和峭壁，山坡上散落的松树和灌木，岸边清澈碧绿的海水，轻柔的小浪",
        "beach_details": "柔软的沙滩上有脚印，两条略带褶皱的毛巾，旁边有一个简单的布袋和一件轻薄的罩衫，无品牌标识",
        "no_luxury_rule": "无海滩俱乐部家具，无遮阳伞，无豪华船只，无度假村氛围",
        "signage_rule": "任何地方都无可见文字或标志"
      },
      "lighting": "明亮的午间阳光带天空补光，皮肤和岩石上的高光受控，阴影深邃但细节丰富"
    }
  }
}

