promptEn:
{
  "vibe_title_en": "Zero-G Laundromat",
  "master_prompt": "A cinematic, hyper-realistic medium shot of The Protagonist standing calmly in the center of a cramped, overflowing retro laundromat. The scene is an explosion of &#x27;frozen daily life&#x27; captured with high-budget practical effects logic. SURREAL ELEMENTS: Time has stopped; hundreds of mismatched socks, swirling soapy water globules that refract light like glass, silver coins, and white detergent powder are suspended in mid-air, floating weightlessly around the subject in a dense, chaotic orbit. The environment is incredibly busy and textured, featuring checkered floor tiles, rows of humming vintage washing machines, and stacks of laundry baskets cluttering the background. Lighting is a mix of dingy overhead fluorescent tubes (green cast) and a warm, soft cinematic key light on the face. Shot on a Hasselblad H6D-100c with an 80mm lens, f/2.8, creating a creamy bokeh that blurs the floating debris in the foreground and background while keeping the subject razor-sharp. The image possesses the organic grain structure of Kodak Portra 800 film, emphasizing skin texture and the tactile reality of the floating objects. No CGI look; purely photographic surrealism.",
  "meta": {
    "intent": "Editorial Fashion / Surreal Art",
    "priorities": "Texture, Density, Surrealism, Lighting quality",
    "device_profile": "High-End Desktop / Large Format Print"
  },
  "frame": {
    "aspect": "4:5",
    "composition": "Central Symmetrical framing with chaotic framing elements",
    "layout": "Subject centered, surrounded by a dense orbital ring of floating objects",
    "camera_angle": "Eye-level, straight on",
    "tilt_roll_degrees": "0 degrees"
  },
  "subject": {
    "gender": "Female",
    "identity": "The Protagonist",
    "demographics": "Universal Template",
