promptEn:
[
  {
    "tasveer_id": "01_ANA_DE_ARMAS",
    "shakhsiyat_ka_naam": "Ana de Armas",
    "photography_style": "Cinematic Portraiture",
    "detailed_description": {
      "expression": "Aankhon mein ek gehri soch aur umeed ki jhalak hai. Woh upar ki janib dakh rahi hain jaise roshni ka intezar kar rahi hon.",
      "lighting_geometry": "Sunlight khidki ke lohay ke frame se guzar kar aa rahi hai, jis se unke chehre aur jism par mustateel (rectangular) saaye ban rahe hain.",
      "color_palette": "Golden aur warm tones ka istemal kiya gaya hai jo skin ko glowing aur scene ko purana (vintage) banata hai.",
      "background_elements": "Piche ki deewar thodi kharab aur rustic hai, jo ek &#x27;shabby chic&#x27; aesthetic paida kar rahi hai."
    },
    "vibe": "Udaasi aur khubsurti ka ek anokha imtiaz (melancholic beauty)."
  },
  {
    "tasveer_id": "02_BILLIE_EILISH",
    "shakhsiyat_ka_naam": "Billie Eilish",
    "photography_style": "High-Angle Soft Focus",
    "detailed_description": {
      "camera_perspective": "Camera ko thoda upar rakha gaya hai jis se Billie ki aankhein bari aur pur-asar lag rahi hain.",
      "skin_and_texture": "Skin ki texture ko bohot natural rakha gaya hai, halki freckles aur pores nazar aa rahe hain jo asaliat (authenticity) ko zahir karte hain.",
      "lighting_effect": "Naram roshni (diffused light) hai, saaye bohot halkay hain jo chehre ki masoomiyat ko barhate hain.",
      "hair_styling": "Siyah baal beech se divide karke piche bandhe gaye hain, jo unke chehre ke frames ko wazeh karte hain."
    },
    "vibe": "Masoomiyat, gehri khamoshi aur minimalist sanjidgi."
  },
  {
    "tasveer_id": "03_SYDNEY_SWEENEY",
    "shakhsiyat_ka_naam": "Sydney Sweeney",
    "photography_style": "High-Contrast Editorial",
    "detailed_description": {
      "visual_impact": "Yeh tasveer sab se zyada &#x27;sharp&#x27; hai. Roshni aur andheray (light & shadow) ka muqabla bohot wazeh hai.",
      "facial_features": "Sydney ki neeli aankhein (blue eyes) roshni mein chamak rahi hain, aur unke honton ka natural pink rang highlight ho raha hai.",
      "shadow_pattern": "Khidki ki jaliyon ka saaya poore chehre aur shano (shoulders) par ek geometric design bana raha hai, jo tasveer ko artistic banata hai.",
      "framing": "Close-up shot jahan sara focus unke chehre ke mizaaj aur huroof par hai."
    },
    "vibe": "Nidarr (bold), wazeh aur pur-kashish (captivating)."
  }
]

promptCh:
[
  {
    "tasveer_id": "01_ANA_DE_ARMAS",
    "shakhsiyat_ka_naam": "{argument name=\"celebrity 1 name\" default=\"Ana de Armas\"}",
    "photography_style": "电影感肖像",
    "detailed_description": {
      "expression": "她的眼中流露出深思与一丝希望。她向上凝视，仿佛在等待光明。",
      "lighting_geometry": "阳光透过窗户的铁框，在她脸上和身体上投射出矩形阴影。",
      "color_palette": "采用金色暖色调，使皮肤焕发光泽，场景充满复古感。",
      "background_elements": "身后的墙壁略显破旧和质朴，营造出一种“破旧别致”的美学。"
    },
    "vibe": "悲伤与美丽独特融合（忧郁之美）。"
  },
  {
    "tasveer_id": "02_BILLIE_EILISH",
    "shakhsiyat_ka_naam": "{argument name=\"celebrity 2 name\" default=\"Billie Eilish\"}",
    "photography_style": "高角度柔焦",
    "detailed_description": {
      "camera_perspective": "相机位置略高，使 Billie 的眼睛看起来大而富有冲击力。",
      "skin_and_texture": "皮肤纹理保持非常自然；细微的雀斑和毛孔清晰可见，展现真实感。",
      "lighting_effect": "使用柔和光线（漫射光），阴影非常浅，增强了面部的纯真感。",
      "hair_styling": "黑色头发中分并向后梳理，突出了她的脸部轮廓。"
    },
    "vibe": "纯真、深沉的寂静和极简的严肃。"
  },
  {
    "tasveer_id": "03_SYDNEY_SWEENEY",
    "shakhsiyat_ka_naam": "Sydney Sweeney",
    "photography_style": "高对比度时尚大片",
    "detailed_description": {
      "visual_impact": "这张照片最“锐利”。光影对比非常清晰。",
      "facial_features": "Sydney 的蓝色眼睛在光线中闪耀，她嘴唇自然的粉色被突出。",
      "shadow_pattern": "窗格的阴影在她脸部和肩部形成几何图案，使照片充满艺术感。",
      "framing": "特写镜头，所有焦点都集中在她脸部的情绪和特征上。"
    },
    "vibe": "大胆、清晰、迷人。"
  }
]

promptEn:
{
  "project_title": "Vintage Glamour Piano Series",
  "common_elements": {
    "subject": "Young woman with dark blonde hair, straight bangs, and red lipstick.",
    "outfit": "Sheer, dusty pink halter-neck bodysuit covered in large iridescent crystals and sequins, with a fringed skirt layer.",
    "environment": "Ornate vintage hotel room with pink damask wallpaper, heavy maroon curtains, patterned beige carpet, and a retro green upright piano.",
    "lighting_and_style": "Direct flash photography, high contrast, vintage aesthetic, fisheye or wide-angle lens distortion, saturated colors, 4k resolution, hyper-realistic textures."
  },
  "frames": [
    {
      "frame_id": 1,
      "position": "Top Left",
      "visual_prompt": "Low-angle fisheye shot. The subject is perched on top of a green upright piano, leaning back with knees bent. One leg is extended dramatically toward the camera lens, making the foot appear larger than life. She wears pink fishnet socks and pink strappy heels with crystal details. The focus is sharp on the texture of the fishnet and shoe in the foreground, blurring slightly toward her face.",
      "pose_details": "Sitting on piano, leg extended, looking away casually."
    },
    {
      "frame_id": 2,
      "position": "Top Right",
      "visual_prompt": "High-angle wide shot looking down at the subject seated at the green piano. She is looking up at the camera with a soft expression. Her right hand rests on the piano keys, fingers spread, showcasing a large ring. The wide-angle lens elongates her arm and hand. The background shows an unmade bed with gold satin sheets and a vintage lamp.",
      "pose_details": "Seated at keys, hand on piano, head tilted up."
    },
    {
      "frame_id": 3,
      "position": "Bottom Left",
      "visual_prompt": "Dynamic medium shot. The subject stands with her back to the camera, turning her head to look over her left shoulder. Her left arm is raised toward the camera, creating a motion-blurred foreground element. The side profile of the bodysuit reveals a backless design and hanging crystal fringe. The lighting highlights the sparkle of the gems and the curve of her shoulder.",
      "pose_details": "Standing/turning away, looking back, arm in motion."
    },
    {
      "frame_id": 4,
      "position": "Bottom Right",
      "visual_prompt": "Close-up extreme wide-angle shot, similar to a 0.5x selfie. The subject leans forward into the lens, distorting the perspective so her head appears larger. She looks directly at the viewer with a piercing gaze. The intricate detailing of the crystal bodice is highly visible. The green piano keys are visible in the lower right corner.",
      "pose_details": "Leaning forward, direct eye contact, close-up."
    }
  ]
}

promptCh:
{
  "project_title": "复古魅力钢琴系列",
  "common_elements": {
    "subject": "一位年轻女子，深金色头发，齐刘海，涂着红色口红。",
    "outfit": "透明的烟粉色露背连体衣，上面镶嵌着大颗虹彩水晶和亮片，下摆是流苏裙摆。",
    "environment": "华丽的复古酒店房间，粉色大马士革壁纸，厚重的酒红色窗帘，图案米色地毯，以及一台复古绿色立式钢琴。",
    "lighting_and_style": "直射闪光摄影，高对比度，复古美学，鱼眼或广角镜头畸变，饱和色彩，4k 分辨率，超真实纹理。"
  },
  "frames": [
    {
      "frame_id": 1,
      "position": "左上",
      "visual_prompt": "低角度鱼眼镜头拍摄。主体栖息在绿色立式钢琴顶部，向后倾斜，膝盖弯曲。一条腿戏剧性地伸向相机镜头，使脚看起来比实际更大。她穿着粉色渔网袜和粉色带状高跟鞋，鞋上有水晶细节。焦点清晰地落在前景的渔网和鞋子的纹理上，向她的脸部略微模糊。",
      "pose_details": "坐在钢琴上，腿伸展，随意地看向别处。"
    },
    {
      "frame_id": 2,
      "position": "右上",
      "visual_prompt": "高角度广角镜头，俯视坐在绿色钢琴旁的主体。她抬起头，带着柔和的表情看向镜头。她的右手放在钢琴琴键上，手指张开，展示着一枚大戒指。广角镜头拉长了她的手臂和手。背景显示一张凌乱的床，铺着金色缎面床单和一盏复古台灯。",
      "pose_details": "坐在琴键旁，手放在钢琴上，头向上倾斜。"
    },
    {
      "frame_id": 3,
      "position": "左下",
      "visual_prompt": "动态中景镜头。主体背对镜头站立，头转向左肩上方。她的左臂抬向镜头，形成一个动态模糊的前景元素。连体衣的侧面轮廓展现出露背设计和悬挂的水晶流苏。灯光突出了宝石的闪光和她肩膀的曲线。",
      "pose_details": "站立/转身，回头看，手臂在运动中。"
    },
    {
      "frame_id": 4,
      "position": "右下",
      "visual_prompt": "特写超广角镜头，类似于 0.5 倍自拍。主体向前倾斜靠近镜头，透视畸变使她的头部显得更大。她直视观众，目光锐利。水晶紧身胸衣的复杂细节清晰可见。绿色钢琴琴键在右下角可见。",
      "pose_details": "身体前倾，直接眼神接触，特写。"
    }
  ]
}

