    "body_and_anatomy": "沙漏型身材，由于姿势和拍摄角度，下半身曲线尤为突出。胸部侧面可见，左侧自然丰满。下背部有明显的深弧度（脊柱前凸）。臀部圆润突出，被服装剪裁所强调。左手抬起，触碰锁骨附近的左上胸/肩部区域。左手外侧/手腕处可见小纹身。",
    "outfit": "一件紧身、长袖的 {argument name=\"dress color\" default=\"淡紫色或浅丁香色\"} 迷你连衣裙（或连体衣/紧身衣）。面料似乎是哑光、有弹性的运动服材料（氨纶/尼龙混纺）。特色是背部有一个大的开放式镂空，露出中背部和上背部。臀部垂直接缝处有独特的褶皱“抓皱”细节，以突出臀形。"
  },
  "pose": {
    "orientation": "站立，背对镜头（背部/后视图），扭转躯干，回头看向左肩。",
    "spine_and_posture": "下背部有明显的弧度。肩膀相对于镜头视角向下倾斜。颈部向左旋转。",
    "limbs": "左臂肘部弯曲，手放在锁骨附近。右臂向下伸展，部分被遮挡。双腿伸直，站立在铺砌的地面上。",
    "head_tilt": "下巴略微内收，脸部向上倾斜，朝向镜头。",
    "details": "赤脚，可见白色脚趾甲油。"
  },
  "environment": {
    "location": "室外车道或庭院区域。",
    "ground": "浅灰色混凝土板或铺路石，可见接缝。",
    "background_elements": "左侧前景有一个纹理米色灰泥柱子或墙壁。背景是模糊的绿色树木和植物，暗示着住宅区或公园般的环境。",
    "depth": "景深较浅；主体清晰，而背景植被柔和且失焦。"
  },
  "camera": {
    "angle": "高角度拍摄（相机位于主体上方，以大约 45 度角向下看）。",
    "framing": "中景全身照，从头顶到脚踝/脚部。",
    "perspective": "透视缩短强调了头部和肩膀，而向脚部逐渐变细。向下角度突出了背部和臀部的曲线。",
    "lens_characteristics": "主体对焦清晰，背景有轻微的焦外虚化（bokeh）。"
  },
  "lighting": {
    "type": "自然日光，可能是阴天或开放式阴影。",
    "quality": "柔和、漫射的光线，皮肤上没有刺眼、直射的阳光高光。"
  }
}

promptEn:
{
  "prompt": "Ultra-realistic candid outdoor lifestyle photograph of me (use my face reference, identity must match exactly). Shot from a slightly elevated angle, camera positioned above eye level looking downward. I am standing still on uneven moss-covered stone steps in a lush green forest. My body is angled about 20–30 degrees away from the camera, shoulders relaxed, posture natural and upright. My head is slightly tilted upward, eyes directed toward the camera. Expression is calm, confident, relaxed, and neutral — no smile, no tension. Appearance: natural hair exactly as in the uploaded reference — dense, healthy hair with natural wave and curl pattern, medium length on top, neatly shaped and groomed, sides subtly tapered but not faded. Hair looks freshly styled for a photo shoot using light product for definition and texture, maintaining a completely natural, effortless look with no artificial shine or exaggerated volume. Full well-groomed beard and mustache. Wearing rectangular black sunglasses with dark lenses. Outfit includes a muted {argument name=\"sweatshirt color\" default=\"sage-green\"} oversized sweatshirt with soft fabric texture, a thin silver chain necklace visible on the neckline, a black cross-body sling bag worn diagonally across the chest, and black trousers (lower body partially visible). Environment: outdoor forest setting with dense green foliage, moss, and natural stone steps. Background feels organic, slightly wild, untouched, and realistic. Lighting: soft natural daylight filtered through trees, overcast or shaded forest light, evenly diffused with no harsh shadows or highlights. Natural skin tones preserved. Camera & realism: DSLR photo realism, 50mm–85mm lens look, medium depth of field, sharp focus on subject, gently softened background. Natural colors with earthy green tones. Visible skin texture and pores, no beauty retouching, no stylization. Mood: effortless masculinity, grounded confidence, modern casual fashion. Feels like a candid frame from a premium outdoor fashion editorial.",
  "negative_prompt": "low quality, cartoon, illustration, anime, painting, over-processed skin, plastic face, smooth skin, beauty retouching, cinematic lighting, dramatic lighting, studio lighting, exaggerated pose, exaggerated emotion, smiling, fashion runway pose, extreme contrast, color grading, blur, noise, grainy, watermark, logo, text, instagram UI, interface elements",
  "style": "photorealistic",
  "camera": {
    "lens": "85mm",
    "aperture": "f/4",
    "angle": "slightly elevated, looking down",
    "focus": "sharp subject, soft background"
  },
  "lighting": "natural diffused daylight",
  "quality": "ultra high realism"
}

promptCh:
{
  "prompt": "一张超逼真的户外生活方式抓拍照片，主体是我（使用我的面部参考，身份必须完全匹配）。拍摄角度略微抬高，相机位于视线水平上方，向下俯视。我静止地站立在郁郁葱葱的绿色森林中长满苔藓的崎岖石阶上。我的身体与相机呈 20-30 度角，肩膀放松，姿势自然挺拔。我的头部略微向上倾斜，眼睛看向相机。表情平静、自信、放松、中性——没有笑容，没有紧张。 外貌：头发与上传的参考照片完全一致——浓密、健康，具有自然的波浪和卷曲纹理，顶部中等长度，修剪整齐，两侧微妙渐变但未褪色。头发看起来像是为拍摄而精心造型的，使用了少量产品来增加层次感和质感，保持完全自然、不费力的外观，没有人工光泽或夸张的蓬松感。蓄有修剪整齐的浓密胡须和胡子。戴着黑色矩形墨镜，镜片颜色深。 服装包括一件柔和的 {argument name=\"sweatshirt color\" default=\"鼠尾草绿\"} 宽松运动衫，面料柔软，领口处可见一条细银链项链，一个黑色斜挎包斜跨胸前，以及黑色长裤（下半身部分可见）。 环境：户外森林场景，有茂密的绿色植物、苔藓和天然石阶。背景感觉有机、略带野性、未经触碰且真实。 光线：穿过树木的柔和自然日光，阴天或林间阴影光线，均匀漫射，没有刺眼的阴影或高光。肤色自然。 相机与真实感：数码单反照片真实感，50mm–85mm 镜头效果，中等景深，主体对焦锐利，背景柔和虚化。自然色彩，带有泥土般的绿色调。可见皮肤纹理和毛孔，无美颜修饰，无风格化。 情绪：不费力的阳刚之气，沉稳的自信，现代休闲时尚。感觉就像是高端户外时尚杂志的抓拍画面。",
  "negative_prompt": "低质量、卡通、插画、动漫、绘画、过度处理的皮肤、塑料脸、光滑皮肤、美颜修饰、电影光、戏剧光、影棚光、夸张姿势、夸张表情、微笑、T 台姿势、极端对比、色彩分级、模糊、噪点、颗粒感、水印、标志、文字、Instagram UI、界面元素",
  "style": "写实摄影",
  "camera": {
    "lens": "85mm",
    "aperture": "f/4",
    "angle": "略微抬高，向下俯视",
    "focus": "主体锐利，背景柔和"
  },
  "lighting": "自然漫射日光",
  "quality": "超高真实感"
}

