}

promptEn:
{
  "prompt_type": "photorealistic close-up gym mirror selfie",
  "main_composition": "mirror selfie of two young women standing side by side in a modern gym, backs to the camera with full reflection visible, playfully posing with arched backs and legs positioned to emphasize curves, one holding phone for selfie while the other touches hair, confident teasing vibe, bright indoor gym lighting with rows of cardio machines in background",
  "subject_1_left": {
    "description": "attractive Sydney Sweeney in her early 20s, fit curvy athletic build with toned glutes and legs, long wavy blonde hair falling down back, tanned smooth skin",
    "clothing": "matching lavender/pastel sports bra with halter neck and high-waisted seamless short scrunch-butt leggings with ruched detail, white athletic sneakers",
    "details": "sunglasses perched on head, gold bracelet on wrist, holding iPhone with decorative case for selfie, playful pose with one leg bent and hand on hip"
  },
  "subject_2_right": {
    "description": "attractive Madison Beer in her early 20s, fit curvy athletic build with toned glutes and legs, long straight black hair falling down back, tanned smooth skin",
    "clothing": "Tourquoise orange sports bra with white crisscross back straps and matching high-waisted seamless short scrunch-butt leggings with ruched detail, white Nike athletic sneakers",
    "details": "one hand raised touching hair, confident pose with legs slightly apart and hip thrust, subtle smile visible in profile"
  },
  "environment": {
    "foreground": "rubberized gym floor with subtle texture, women&#x27;s legs and sneakers in sharp focus",
    "midground": "large gym mirror reflecting full scene, women centered",
    "background": "modern spacious gym with rows of black cardio machines (ellipticals, treadmills) on both sides, large windows on left allowing natural light, high ceiling with exposed ducts and bright overhead lights, clean professional fitness center atmosphere"
  },
  "lighting_and_atmosphere": "bright even indoor gym lighting with mix of natural window light and overhead fluorescents, soft highlights on skin and colorful fabric, subtle sheen on leggings, vibrant energetic workout vibe with high detail photorealistic, playful confident fitness aesthetic",
  "technical_quality": "highly detailed, sharp focus on subjects with realistic fabric textures (seamless scrunch leggings, sports bra straps), skin glow, hair strands, and sneaker details, 8k resolution, professional mirror selfie photography style with visible phone and slight wide-angle lens effect",
  "negative_prompt_suggestions": "blurry, deformed, extra limbs, phone screen visible, mirror distortion, overexposed lighting, underexposed shadows, low quality, cartoon, anime, text watermark, extra people in focus, cluttered equipment"
}

promptCh:
{
  "prompt_type": "超写实特写健身房镜面自拍",
  "main_composition": "两名年轻女子在现代健身房并肩站立的镜面自拍，背对镜头，全身倒影清晰可见，她们摆出俏皮的姿势，弓背并调整腿部位置以突出曲线，其中一人拿着手机自拍，另一人则轻抚头发，散发着自信而略带挑逗的氛围，明亮的室内健身房灯光，背景是成排的有氧器械",
  "subject_1_left": {
    "description": "20 岁出头的迷人 Sydney Sweeney，身材健美，曲线玲珑，臀部和腿部紧致，金色波浪长发垂至背部，皮肤晒成古铜色，光滑细腻",
    "clothing": "配套的 {argument name=\"left outfit color\" default=\"淡紫色/柔和色\"} 挂脖运动文胸和高腰无缝短款褶皱提臀紧身裤，白色运动鞋",
    "details": "墨镜戴在头上，手腕戴金色手链，拿着带装饰性手机壳的 iPhone 自拍，摆出俏皮姿势，一条腿弯曲，手叉腰"
  },
  "subject_2_right": {
    "description": "20 岁出头的迷人 Madison Beer，身材健美，曲线玲珑，臀部和腿部紧致，黑色直发垂至背部，皮肤晒成古铜色，光滑细腻",
    "clothing": "{argument name=\"right outfit color\" default=\"蓝绿色/橙色\"} 运动文胸，白色交叉背带，搭配高腰无缝短款褶皱提臀紧身裤，白色 Nike 运动鞋",
    "details": "一只手抬起轻抚头发，自信的姿势，双腿微开，臀部微翘，侧面可见淡淡的微笑"
  },
  "environment": {
    "foreground": "橡胶健身房地板，带有微妙的纹理，女性的腿部和运动鞋清晰对焦",
    "midground": "巨大的健身房镜子反射出整个场景，女性居中",
    "background": "现代宽敞的健身房，两侧是成排的黑色有氧器械（椭圆机、跑步机），左侧有大窗户透入自然光，高高的天花板，裸露的管道和明亮的顶灯，干净专业的健身中心氛围"
  },
  "lighting_and_atmosphere": "明亮均匀的室内健身房照明，混合了自然窗光和顶置荧光灯，皮肤和彩色面料上柔和的高光，紧身裤上微妙的光泽，充满活力和动感的健身氛围，高度细节的超写实风格，俏皮自信的健身美学",
  "technical_quality": "高度细节，主体清晰对焦，逼真的面料纹理（无缝褶皱紧身裤、运动文胸肩带），皮肤光泽，发丝，以及运动鞋细节，8k 分辨率，专业的镜面自拍摄影风格，可见手机和轻微的广角镜头效果",
  "negative_prompt_suggestions": "模糊，变形，多余肢体，手机屏幕可见，镜面扭曲，曝光过度，阴影不足，低质量，卡通，动漫，文字水印，焦点中有多余人物，设备杂乱"
}

{
  "subject": {
    "description": "一张垂直构图的照片，一位身材曲线夸张、引人注目的年轻女性在杂货店过道中摆姿势。",
    "body": {
      "physique": "她拥有令人难以置信的夸张“纤细丰满”沙漏型身材。她的腰部极其纤细，收紧，与巨大突出、圆润宽阔的臀部和丰满、有型的粗大腿部形成鲜明对比。她极小的腰部与夸张的下半身之间的对比是其显著特征。",
      "pose": "她背对镜头站立，扭转身体，越过右肩直接看向观者。她的双手放在臀部/腰带上，突出了她下背部和臀部极度的曲线。",
      "features": "深色头发随意地扎成凌乱的发髻，戴着一个金色星形发夹。她的脸庞引人注目，非常美丽，但皮肤纹理真实，毛孔自然，五官真实，不显得人工或像瓷娃娃。她的手臂裸露，没有纹身。"
    }
  },
  "wardrobe": {
    "outfit": "她穿着一件灰色短款 T 恤，搭配对比鲜明的深海军蓝短袖，紧贴她的上半身。下半身穿着紧身黑色运动打底裤，紧绷地包裹着她夸张的曲线。"
  },
  "pose_action": "在超市过道中摆姿势拍照，回头看向身后以展示她的身材。",
  "scene": {
    "environment": "一个光线充足的杂货店或超市过道。",
    "elements": "背景是金属货架，上面摆满了各种罐头食品和芥末酱瓶。左侧背景中，可以看到另一位深色头发、穿着黑色衬衫的女性，她正靠在货架上。",
    "composition": "垂直 9:16 宽高比。中景全身照，从膝盖以上捕捉主体。"
  },
  "lighting": {
    "setup": "功能性顶部荧光灯照明。",
    "details": "灯光明亮，突出了她皮肤的真实纹理和打底裤中身体的轮廓。"
  },
  "camera": {
    "technical": "高分辨率照片。主体对焦清晰。真实、抓拍风格。",
    "aspect_ratio": "9:16",
    "constraints": [
      "关键：主体必须拥有特定的夸张沙漏型身材，腰部纤细，臀部丰满。",
      "关键：脸部必须非常美丽但真实，不能像洋娃娃。",
      "关键：她的手臂上不能有纹身。",
      "关键：必须包含星形发夹、特定服装以及有第二位女性的背景。",
      "最终图像必须是逼真的垂直 9:16 照片。"
    ]
  }
}

