    "anatomical_fidelity": {
      "bust_volume": "胸部极其丰满沉重，远超平均尺寸。乳房呈现出自然的重量和下垂感，位置较低且饱满。比基尼上衣难以完全包裹住其体积，形成了深陷的乳沟和显著的突出。",
      "proportions": "准确展现了丰满、胸部饱满的自然身材。肩膀柔和，略带圆润。比基尼肩带压迫颈部和皮肤处可见软组织变形。红色系带在皮肤上留下了淡淡的压痕。",
      "skin_details": "高保真度的皮肤纹理，可见毛孔、自然肤色不均、痣以及水润的光泽。在水线以上暴露于冷空气中的上臂和肩膀处，隐约可见鸡皮疙瘩。"
    }
  },
  "pose": {
    "type": "特写自拍",
    "orientation": "身体略微偏向观者的左侧。脸部朝向镜头。",
    "head_position": "头部略微向右倾斜，下巴微微内收。",
    "limbs": {
      "left_arm": "向前伸出，并超出画面右下角，明显正在握持相机设备（自拍姿势）。",
      "right_arm": "部分浸没在水中，靠近木桶边缘。几片散落的红色玫瑰花瓣漂浮在她前臂旁的水中。",
      "spine_curvature": "身体略微前倾。"
    }
  },
  "environment": {
    "setting": "情人节傍晚日落后，室外冬季热水浴缸。",
    "water_surface": {
      "description": "深色、冒着蒸汽的水面，可见缕缕蒸汽升腾，尤其是在冷空气与热水交汇处。",
      "floating_elements": [
        "水面上漂浮着零散的红色和深粉色玫瑰花瓣——并非完美排列，有些被水流自然地聚集在一起，有些则单独漂浮，少数花瓣因吸水而略显半透明，另一些则依然新鲜，边缘微微卷曲。",
        "一朵完整的深红色玫瑰花漂浮在花瓣之间，花茎修剪得很短，部分浸没在水中，外层花瓣上凝结着水珠。",
        "两到三支小型漂浮茶蜡，装在简单的金色锡箔杯中，火焰低矮且摇曳不定——其中一支火焰被微风吹得略微倾斜，蜡池内部散发着温暖的橙色光芒。"
      ]
    },
    "tub_elements": [
      "质朴的木制热水浴缸木板，因潮湿而颜色深沉"
    ]
  }
}

