promptEn:
{
  "prompt": "A hyper-realistic, high-fashion editorial photograph of a stunning woman seated on the floor of a minimalist art gallery corridor. She has shoulder-length, wavy brunette hair parted to the side and soft, natural makeup with rose-colored lips. She is leaning slightly back against a smooth, beige wall. She wears a fitted, taupe-colored satin slip top with spaghetti straps and a plunging neckline. An oversized, textured cream-colored shearling or faux-fur coat is draped loosely off her shoulders, resting around her elbows and lower back. She is wearing elegant black strappy high-heeled sandals with delicate ankle ties. Her legs are angled, knees bent. The lighting is warm and cinematic, casting soft shadows against the wall. The background is slightly out of focus (depth of field), showing a hallway with framed artworks and polished stone flooring. 8k resolution, incredibly detailed skin texture, sharp focus on the subject, shot on 35mm film.",
  "subject_details": {
    "hair_color": "dark brown",
    "hair_style": "shoulder length, loose waves, side swept",
    "skin_tone": "light olive",
    "expression": "calm, alluring, direct gaze",
    "pose": "sitting on floor, leaning against wall, legs bent, hands resting on floor and leg"
  },
  "clothing_and_accessories": {
    "top": "taupe spaghetti strap slip camisole or dress",
    "outerwear": "off-white fuzzy shearling jacket, draped off-shoulder",
