  "settings": {
    "resolution": "1024x1792",
    "lighting": "golden hour",
    "style": "realistic photography",
    "camera": "35mm lens, shallow depth of field"
  }
}

promptCh:
{
  "prompt": "一位俏皮的金发女子在主题公园的童话城堡前，于黄金时段摆姿势。她站在鹅卵石小路上，背景是城堡粉蓝色的小塔楼。她穿着红色运动短裤和白色网眼背心，上面印有小猫图案和字母“ATM”，并微微提起衣摆。她背着一个红色单肩包，化着柔和的自然妆容，吐着舌头微笑，表情有趣而无忧无虑。温暖的日落光线，鲜艳的色彩，浅景深，高分辨率，抓拍旅行摄影风格。",
  "negative_prompt": "模糊，低分辨率，脸部扭曲，多余肢体，过曝，欠曝，水印，文字伪影",
  "settings": {
    "resolution": "1024x1792",
    "lighting": "golden hour",
    "style": "realistic photography",
    "camera": "35mm lens, shallow depth of field"
  }
}

