      "style": "analog contact sheet look with black slide mounts around each frame, slight dust/scratches, subtle light leaks",
      "mood": "moody, sensual, editorial, not explicit"
    },
    "subject": {
      "person": "adult woman",
      "hair": "long dark hair, natural volume",
      "makeup": "soft smoky eyes, glossy lips, warm blush under red light",
