      ],
      "accent": [
        "deep balloon blue",
        "sunset orange",
        "mustard yellow"
      ],
      "grade": {
        "white_balance": "warm daylight (~5200K)",
        "saturation": "moderate, natural cinematic tone",
        "tone_curve": "soft highlight roll-off, warm mids, clean shadows"
      }

