    "face": "侧脸，舌头俏皮地伸向一侧，目光注视着镜子中的手机屏幕。下颌线分明，眉毛修剪整齐，可见睫毛和唇色等妆容。",
    "body_type": "曲线优美、肌肉发达的健身身材。肩部（三角肌）和手臂肌肉线条清晰可见。腰部纤细，腹部平坦，臀部因姿势而显得宽大突出，胸部丰满，侧面可见。",
    "skin": "白皙的肤色，质感真实，手臂和背部有微妙的阴影勾勒出肌肉线条。",
    "clothing": "白色细肩带运动文胸或露脐上衣。浅麻灰色紧身短裤（针织质地），低腰设计。"
  },
  "pose": {
    "type": "站立式镜面自拍，3/4 背面角度。",
    "details": "身体背对镜头（3/4 背面视角）。躯干略微向左扭转，面向镜子。背部弓起（骨盆前倾），以突出臀部。头部转向左肩。左臂弯曲，举起智能手机拍照。右臂放松垂在身侧，肘部略微弯曲。腿部在画面底部被截断于大腿中部。",
    "gesture": "舌头伸出，姿态俏皮、玩味。手持手机，手指上戴有戒指。"
  },
  "environment": {
    "setting": "室内房间，可能是卧室或更衣室。",
    "background": "纯色、浅灰色或米白色墙壁。左侧可见垂直的接缝或门框边缘。表面是镜子，手机左侧玻璃上可见污迹。",
    "lighting_interaction": "主体在身后墙壁上投下阴影。"
  },
  "camera": {
    "shot_type": "镜面自拍，中景。",
    "perspective": "相对于反射物体的视线水平。图像中看到的手机即为相机。",
    "device_visible": "左手拿着一部银色/透明手机壳的 Apple iPhone Pro 型号（三镜头）。",
    "focal_length": "24-28 毫米等效焦距（标准智能手机广角）。",
    "framing": "垂直构图，头部顶部和大腿中部被截断。"
  },
  "lighting": {
    "type": "柔和的室内环境光。",
    "direction": "相对于主体，光线来自上方和略微前方。",
    "quality": "漫射光，在墙壁上形成柔和的阴影，并勾勒出手臂和背部的肌肉结构。",
    "shadows": "主体侧影在左肩后方的墙壁上投下清晰的阴影。",
    "highlights": "金发、肩膀和脸颊上柔和的高光。"
  },
  "mood_and_expression": {
    "mood": "俏皮、自信、轻佻、随意。",
    "expression": "伸舌头的俏皮姿态，自信的肢体语言展示健身成果。"
  },
  "style_and_realism": {
    "style": "社交媒体风格"
  }
}

