promptEn:
{
  "aspect_ratio": "4:5",
  "prompt": {
    "subject": {
      "description": "An adult woman inspired by Sadie Sink (not an exact replica). Fair skin with visible light freckles across cheeks, shoulders, and arms. Soft-glam nightclub makeup with dewy highlights, defined brows, subtle eyeliner, and a muted rosy nude lip. Long straight copper-auburn hair with a clean center part, sleek and glossy under club lights. Expression is confident and slightly teasing, looking back over her shoulder directly at the camera.",
      "clothing": "Bottle-service outfit: a tight red satin/lycra bodysuit with thin spaghetti straps and high-cut legs, form-fitting with smooth seams. Minimal jewelry: a delicate choker/short chain necklace. No visible logos or branding.",
      "pose": "She stands in a nightclub aisle, body turned away while twisting her upper torso back toward the camera. One arm is raised overhead holding a tall dark glass bottle upright near her head, elbow bent; the other arm rests close to her body. Framing is mid-to-full body from head to upper thighs, emphasizing the over-the-shoulder look."
    },
    "environment": {
      "location": "Crowded nightclub interior near the dance floor / VIP walkway.",
      "details": "Strong neon-magenta and red club lighting with haze in the air. Blurred silhouettes of clubgoers in the background, bokeh light dots, and a glossy reflective floor/walkway edge with LED-like highlights.",
      "background": "Out-of-focus crowd and club fixtures, giving a lively nightlife atmosphere; no readable signage, no recognizable logos, no distinct faces in sharp focus."
    },
    "lighting_and_quality": {
      "lighting": "Low-light nightclub scene with vivid magenta/red lighting and soft rim highlights on hair and shoulders; realistic camera exposure with clean sharp subject and strong background bokeh (no harsh flash).",
      "resolution": "4K HD quality, highly detailed textures on freckles, skin sheen, bodysuit fabric, hair strands, bottle reflections, and atmospheric haze.",
      "style": "Realistic candid nightlife photo taken by someone else (not a selfie), shallow depth of field, subject crisp and centered, no text, no watermark, no logos."
    }
  }
}

promptCh:
{
  "aspect_ratio": "4:5",
  "prompt": {
    "subject": {
      "description": "一位受 Sadie Sink 启发（但并非完全复制）的成年女性。皮肤白皙，脸颊、肩膀和手臂上可见浅色雀斑。柔和迷人的夜店妆容，带有水润高光、精致眉毛、细致眼线和柔和的玫瑰裸色唇妆。长而直的红铜色头发，干净的中央分界线，在夜店灯光下显得光滑亮泽。表情自信，略带挑逗，回头直接看向镜头。",
      "clothing": "酒水服务员服装：一件紧身红色缎面/莱卡连体衣，细吊带，高开叉腿部，修身且接缝平滑。极简首饰：一条精致的颈链/短项链。无可见的标志或品牌。",
      "pose": "她站在夜店过道中，身体背对镜头，但上半身扭转回来面向镜头。一只手臂举过头顶，手持一个高大的深色酒瓶，靠近头部，手肘弯曲；另一只手臂靠近身体。构图为从头部到大腿上部的中景至全身，强调回眸的姿态。"
    },
    "environment": {
      "location": "舞池/VIP 通道附近拥挤的夜店内部。",
      "details": "强烈的霓虹洋红色和红色夜店灯光，空气中弥漫着薄雾。背景中模糊的夜店顾客剪影、散景光点，以及带有 LED 般高光的光滑反光地板/通道边缘。",
      "background": "失焦的人群和夜店设施，营造出热闹的夜生活氛围；没有可辨识的招牌，没有可识别的标志，没有清晰聚焦的独特面孔。"
    },
    "lighting_and_quality": {
      "lighting": "低光照的夜店场景，带有鲜艳的洋红色/红色灯光，头发和肩膀上有柔和的轮廓光；真实的相机曝光，主体清晰锐利，背景散景强烈（无刺眼闪光）。",
      "resolution": "4K 高清画质，雀斑、皮肤光泽、连体衣面料、发丝、酒瓶反光和大气薄雾上都有高度详细的纹理。",
      "style": "由他人拍摄的真实抓拍夜生活照片（非自拍），景深较浅，主体清晰居中，无文字，无水印，无标志。"
    }
  }
}

