{
  "subject": {
    "description": "一张竖版照片，一位身材曲线夸张、异常美丽的年轻女子，在沙滩日落时分摆姿势。",
    "body": {
      "physique": "她拥有令人难以置信的夸张“纤腰丰臀”沙漏型身材。她的腰部极其纤细紧致，与极其突出、圆润、宽大的臀部和丰满、有型的腿部形成鲜明对比。她极小的腰部与夸张的下半身之间的对比是其显著特征。",
      "pose": "站在水边柔软的沙滩上。她身体略微扭转，越过右肩直接看向观者，重现了之前场景中的确切姿势。她的姿态强烈突出了她下背部和臀部的极致曲线。",
      "features": "头发随意地挽成凌乱的发髻，戴着一个金色星形发夹。她的脸庞异常美丽动人，但皮肤纹理真实，毛孔自然，五官真实，没有人工痕迹。她的身体除了比基尼外是裸露的，并且没有纹身。"
    }
  },
  "wardrobe": {
    "outfit": "她穿着一套现代简约的白色两件式比基尼。上衣时尚且有支撑力，下装是高开衩（俏皮款式），紧密贴合并展现她夸张的曲线。"
  },
  "pose_action": "在黄金时段的海边站立，越过肩膀看向镜头。",
  "scene": {
    "environment": "一个美丽、风景优美的沙滩，正值日落时分。",
    "elements": "她站在金色的沙滩上，身后是轻柔拍打脚踝的碧绿海浪。背景是广阔的海平面，日落天空充满温暖的橙色、粉色和紫色。附近没有其他人。",
    "composition": "竖版 9:16 宽高比。一个中景全身镜头，从膝盖以上捕捉主体，以海滩为背景。"
  },
  "lighting": {
    "setup": "日落时分，美丽、温暖的自然黄金光线。",
    "details": "太阳的低角度在她皮肤上营造出温暖的光泽，突出了白色比基尼面料的质感，并在沙滩上投下柔和、长长的阴影，增强了肌肉线条和曲线。"
  },
  "camera": {
    "technical": "高分辨率专业照片。主体对焦清晰。逼真、自然的沙滩风格捕捉。",
    "aspect_ratio": "9:16",
    "constraints": [
      "关键：主体必须拥有特定的夸张沙漏型身材，腰部纤细，臀部丰满。",
      "关键：脸部必须异常美丽但真实。",
      "关键：不能有纹身。",
      "关键：服装必须是现代白色比基尼。",
      "关键：场景必须是日落时的海边沙滩。",
      "最终图像必须是逼真的竖版 9:16 照片。"
    ]
  }
}

