{
  "subject": {
    "description": "一张垂直拍摄的闪光灯照片，一位身材曲线夸张、美得惊人的年轻女子，在夜晚的沙滩上摆姿势。",
    "body": {
      "physique": "她拥有令人难以置信的夸张“纤细丰满”沙漏型身材。她的腰部极其纤细，与极其突出、圆润、宽阔的臀部以及丰满、有型的双腿形成鲜明对比。姿势和直射光线极大地强调了这种对比。",
      "pose": "站在靠近水边的黑暗沙滩上。她身体略微扭转，回头看向右肩，直接对着镜头，重复了之前的姿势。她的站姿在刺眼的光线下突出了她下背部和臀部的极致曲线。",
      "features": "铂金色头发扎成高马尾。她的脸庞美得惊人但又真实，被直射闪光灯强烈照亮，展现出自然的皮肤纹理和毛孔。没有纹身。"
    },
    "wardrobe": {
      "outfit": "一件高度现代、极简主义的鲜红色细带比基尼，设计有多条细带。上衣是微三角形款式，带有复杂的细带细节，下装是超高开衩和极度暴露的款式，带有多个侧边细带，最大限度地展现了她的曲线。"
    }
  },
  "pose_action": "夜晚站在海边，回头看向肩膀，被相机闪光灯照亮。",
  "scene": {
    "environment": "深夜的沙滩。",
    "elements": "她站在黑暗潮湿的沙滩上。她身后是漆黑的海洋，海浪泛着细微的白色泡沫。夜空清澈黑暗，一轮明亮的满月和无数可见的星星点缀其间。",
    "composition": "垂直 9:16 宽高比。一个中景全身镜头，从膝盖以上捕捉主体，闪光灯照明在黑暗的夜景背景下占据主导地位。"
  },
  "lighting": {
    "setup": "刺眼的、直射的、机载闪光灯（如明亮的智能手机闪光灯）与环境月光相结合。",
    "details": "直射闪光灯在主体上形成明亮的聚光灯，使她的皮肤和红色比基尼在锐利的高光下显得格外醒目，并在她身后的沙滩上形成清晰、生硬的阴影。背景元素（月亮、星星、水）可见，但比闪光灯照亮的主体暗得多。闪光灯在潮湿的沙滩和她的皮肤上形成锐利的反光。"
  },
  "camera": {
    "technical": "原始的、抓拍风格的照片，使用直射闪光灯拍摄。主体对焦清晰。高对比度图像，未照明区域有深黑色，主体上有明亮、有些刺眼的高光，这是直射闪光摄影的典型特征。较暗区域可见颗粒感。",
    "aspect_ratio": "9:16",
    "constraints": [
      "关键：主体必须具有特定的夸张沙漏型身材。",
      "关键：光线必须是夜晚刺眼的、直射的手机闪光灯风格。",
      "关键：背景必须包含一个模糊的海洋和天空，有月亮和星星。"
    ]
  }
}

