promptEn:
{
  “meta”: {
    “quality”: “ultra_photorealistic,
    raw style,
    8k”,
    “camera”: “iPhone 15 Pro Max”,
    “lighting”: “bright indoor daylight mixed with soft,
    warm golden lamplight from multiple vintage lamps with white shades,
    casting a cozy and warm golden glow”,
    “style”: “authentic candid fashion portrait,
    detailed textures”,
    “aspect_ratio”: “9:16”
  },
  “scene”: {
    “location”: “A detailed opulent greenhouse restaurant interior,
    with exposed red industrial steel trusses supporting a glass ceiling. Seating includes dark leather tufted booth alcoves. Circular wooden tables and dark wood chairs rest on a large red and black geometric patterned rug. Multiple antique white lamps are distributed among abundant green plants.”,
    “atmosphere”: “Opulent,
    warm,
    vibrant greenhouse dining.”
  },
  “subject”: {
    “gender”: “female”,
    “name”: “Sabrina Carpenter”,
    “body”: {
      “type”: “Realistic,
      naturally proportioned figure,
      accurate to her build.”
    },
    “face”: {
      “features”: “Natural blonde hair styled into a sophisticated,
      voluminous bun with natural textures. Minimal natural makeup. Small gold hoop earrings.”,
      “expression": “A direct, confident gaze toward the camera lens, like a high-fashion model.” }, “outfit”: {“description”: “A tailored, corset-style white strapless mini dress featuring intricate lace panels, decorative white bows on the bust and shoulders, and a fully ruched skirt. Matching pristine white sheer over-the-knee stockings that stop explicitly just above the knee, paired with white pointed-toe stiletto heels.”, “fit”: “Realistic structured fabric and lace, comfortably draped.” }, “pose”: “Sabrina is seated comfortably and poised in the exact center of a deep dark leather tufted booth armchair, crossing her legs at the knee. Her composed expression is directed toward the camera lens. Her bare legs and the white sheer over-the-knee stockings are clearly visible.”, “composition”: “A single focused, three-quarter length vertical shot from a slightly angled perspective (sideways, capturing her from a slightly off-center angle, emphasizing her profile and the texture of her dress), closer than a full-body shot. The focus is sharp on Sabrina and her intricate outfit, with the greenhouse background and abundant plants rendering into a soft, textured blur. The closer framing captures the detail of her bun, makeup, and the intricate lace and structure of the corset dress, while still clearly showing the stocking line just above her crossed knee.” } }

