  "LOCATION": "现代健身房环境",
  "THEME": "健身动力、力量、自我提升",
  "VIBE": "赋能、活力、励志"
}

{
  "subject": {
    "description": "一张垂直构图的照片，一位身材曲线夸张、美得惊人的年轻女子，在夜间的加油站给汽车加油。",
    "body": {
      "physique": "她拥有极其夸张的“纤细丰满”沙漏型身材。她的腰部非常纤细，收紧，与极其突出、圆润、宽大的臀部以及丰满、有型的双腿形成鲜明对比。她极小的腰部与夸张的下半身之间的对比是其显著特征。",
      "pose": "她站在加油泵旁，将油枪插入汽车。她身体略微扭转，越过右肩直接看向观者，姿势与之前类似。她的站姿突出了她下背部和臀部极度的曲线。",
      "features": "深色头发随意地扎成凌乱的发髻，戴着一个金色星形发夹。她的脸庞美得惊人，但皮肤纹理真实，毛孔自然，五官真实，不显人工或像瓷娃娃。她的手臂裸露，没有纹身。"
    }
  },
  "wardrobe": {
    "outfit": "她穿着一件紧身包裹上半身的 {argument name=\"top color\" default=\"浅黄色\"} 短款 T 恤。下半身穿着紧身 {argument name=\"legging color\" default=\"灰色\"} 运动打底裤，紧绷地勾勒出她夸张的曲线。"
  },
  "pose_action": "在夜间的加油站给她的汽车加油，回头看。",
  "scene": {
    "environment": "一个灯火通明的夜间加油站。",
    "elements": "她站在一辆明亮的 {argument name=\"car color\" default=\"粉色\"} Mini Cooper 汽车旁边，正在插入油枪。背景显示了加油泵、混凝土地面、带有工业照明的顶棚结构，以及远处在漆黑夜空映衬下灯火通明的便利店招牌。",
    "composition": "垂直 9:16 宽高比。一个中景全身镜头，捕捉了她从膝盖以上加油时的画面。"
  },
  "lighting": {
    "setup": "夜间混合照明：明亮的顶棚荧光灯投射出强烈的光线和清晰的阴影，与加油站霓虹灯的辉光混合在一起。",
    "details": "人造光线突出了她皮肤的真实纹理、浅黄色上衣和灰色打底裤的面料，以及粉色汽车的光泽漆面。"
  },
  "camera": {
    "technical": "高分辨率照片。主体对焦锐利。在夜间捕捉到的真实、自然的风格。",
    "aspect_ratio": "9:16",
    "constraints": [
      "关键：主体必须拥有特定的夸张沙漏型身材，腰部纤细，臀部丰满。",
      "关键：脸部必须美得惊人但真实，不能像娃娃。",
      "关键：她的手臂上不能有纹身。",
      "关键：服装颜色必须是浅黄色上衣和灰色打底裤。",
      "关键：场景必须是夜间的加油站，有一辆粉色 Mini Cooper。",
      "最终图像必须是逼真的照片。"
    ]
  }
}

