promptCh:
{
  "subject_and_pose": {
    "description": "一张逼真、细节丰富的照片，展现了美丽的 {argument name=\"celebrity name\" default=\"Sydney Sweeney\"}，她留着齐肩的铂金色头发，配有柔和的刘海。她的肤色白皙，带有明显的油亮湿润光泽，暗示着她刚刚游过泳。她的面部表情平静而迷人，直视镜头。",
    "pose": "她跪在泳池的瓷砖边缘，身体微微前倾，右手平放在泳池甲板上支撑身体，左臂则自然地垂在身侧。她的姿态优雅，凸显出健美的沙漏型身材。"
  },
  "outfit": {
    "description": "她穿着一件紧身、有光泽的连体竞技泳衣。",
    "details": "泳衣采用双色设计，中央是深 {argument name=\"primary color\" default=\"royal blue\"} 色，两侧是鲜艳的 {argument name=\"secondary color\" default=\"bubblegum pink\"} 色面板，勾勒出身体曲线。材质具有高光泽度，呈现出类似乳胶或湿润莱卡的质感。胸部上方有一个小小的粉色标志。"
  },
  "environment": {
    "setting": "一个高档的户外度假泳池区，阳光明媚。",
    "background": "近景是波光粼粼的蓝色泳池水，水面下可见蓝色马赛克瓷砖。更远处是泳池边的露台，摆放着白色躺椅、郁郁葱葱的绿色树篱、棕榈树，以及一栋带有木制凉棚屋顶的别墅式建筑，营造出热带夏日氛围。"
  },
  "lighting_and_shot": {
    "lighting": "明亮、高调的自然阳光。主体湿润的皮肤和光泽的泳衣上呈现出强烈的镜面高光，增强了质感和真实感。光线形成了清晰但柔和的阴影，这是正午阳光的典型特征。",
    "camera_shot": "中景全身镜头，捕捉主体从膝盖以上的部分。拍摄角度略高，从上往下俯视主体，以泳池为背景。图像清晰、高分辨率，景深较浅，使主体保持清晰对焦，而背景元素则略微模糊。宽高比 9:16。"
  }
}

