  "subject": {
    "description": "一位二十出头的年轻女性，身材丰满，曲线玲珑。皮肤晒成古铜色，带有自然纹理。深棕色头发挑染了粗重的金色（巴拉亚日染发），梳成两条长辫垂在背后，脸颊两侧有几缕金色发丝散落。",
    "anatomy": {
      "body_type": "沙漏型身材，下半身曲线突出。臀部视觉上占据主导，饱满圆润，紧身衣物进一步凸显了这一点。腰部纤细。肩膀放松。",
      "bust": "侧面可见，胸部适中至丰满，自然下垂，被无肩带上衣包裹。",
      "arms": "左臂可见，上面有几处精细的黑色纹身：上臂二头肌处矩形框内的“BABE”字样，前臂上的一朵花/玫瑰，以及其他小符号。",
      "face": "鹅蛋脸，下颌线分明。妆容包括精致的飞翼眼线、雕塑般的眉毛和哑光紫红色口红。表情是柔和的嘟嘴，带着自信、性感的凝视。"
    },
    "clothing": {
      "top": "黑色无肩带抹胸（裹胸），紧身，露脐。",
      "bottoms": "紫红色/灰粉色紧身运动短裤，背面有“提臀”或褶皱缝线细节，以凸显臀部。短裤两侧有带纽扣翻盖的工装风格口袋。"
    }
  },
  "pose": {
    "type": "坐姿扭转。",
    "description": "主体坐在木凳上，身体背对镜头。她将躯干向左扭转，越过左肩回头直视观者。背部略微弓起。左手抬起，俏皮地抓着左侧辫子的末梢。双腿弯曲，稳稳地坐着。",
    "orientation": "后四分之三视角，脸转向镜头。"
  },
  "environment": {
    "setting": "现代、明亮的住宅室内，可能是客厅或阳光房。",
    "details": [
      "左侧有一个大型盆栽人造橄榄树，放在编织篮中。",
      "浅色木地板。",
      "背景是落地式推拉玻璃门。",
      "透过玻璃，可见室外露台，有白色凉棚、户外餐桌和椅子。",
      "户外在明亮的日光下可见树木和绿植。"
    ]
  },
  "camera": {
    "shot_type": "中景（大腿以上）。",
    "perspective": "略高于视线水平，俯视坐着的主体。",
    "focal_length": "50mm 至 85mm 人像镜头。",
    "depth_of_field": "主体清晰对焦，背景略微柔化但细节丰富（f/2.8 或 f/4）。"
  },
  "lighting": {
    "type": "自然日光与室内环境光混合。",
    "direction": "强烈的自然光从背景（玻璃门）射入，在头发和肩膀上形成轮廓光效果。",
    "quality": "面部光线柔和、漫射（补光），最大程度减少刺眼的阴影。",
    "shadows": "主体背部和凳子下方有柔和的阴影。"
  },
  "mood_and_expression": {
    "mood": "自信、网红美学、放松、略带挑逗。"
  }
}

