promptCh:
{
  "image_generation_prompt": {
    "subject": {
      "description": "一位年轻女性，留着长直浅棕色头发，面带一丝友善的微笑。",
      "pose": "坐在剧院包厢座位上，身体略微侧向远离镜头，但头部转向面对观众。左臂随意地搭在红色天鹅绒包厢栏杆上。",
      "clothing": "{argument name=\"clothing\" default=\"黑色缎面吊带连衣裙，低背设计，下背部有一个大大的黑色装饰蝴蝶结。\"}",
      "accessories": "左手腕戴着金属表带的 Apple Watch，精致的手链，小耳环。",
      "expression": "放松、快乐，眼神交流富有吸引力。"
    },
    "environment": {
      "location": "宏伟的历史悠久的欧洲歌剧院内部（类似于维也纳国家歌剧院）。",
      "architecture": "多层私人包厢座位（loge），饰有华丽的金色巴洛克/洛可可式雕花和灰泥装饰。包厢内有深红色天鹅绒窗帘和墙面覆盖物。",
      "background_details": "她身后可见多层阳台，坐满了其他穿着正装的观众。壁灯和剧院吊灯散发出温暖的环境光。",
