  "subject": {
    "description": "一张韩国魅力女偶像在卧室里的 2x2 镜面自拍拼贴画。图像呈现出独特的“拖影快门”效果，主体被闪光灯照亮，但由于移动而略显模糊，营造出梦幻、朦胧的美感。",
    "vibes": "性感而纯真，亲密，微醺（沉醉于氛围），氛围感，低保真美学。",
    "looks": {
      "face": "柔和的五官，因柔光滤镜而散发光泽的肌肤，“水彩画”般的妆容质感",
      "eyes": "梦幻般的凝视，其中一格略微失焦，另一格则带着柔和的微笑直视镜头",
      "hair": "黑色长发，随运动模糊而摆动，形成丝滑的轨迹"
    }
  },
  "clothing": {
    "style": "纯洁性感的居家服",
    "item": "一件白色丝绸吊带裙或一件半透明的宽松白色 T 恤，滑落一侧肩膀",
    "texture": "丝绸或柔软的棉质，在闪光灯和柔光滤镜下泛着光泽",
    "details": "隐约可见的锁骨，随意的凌乱感"
  },
  "pose": {
    "action": "活泼动感的姿势。非静态。",
    "panels": [
      "第一格：转头时大笑，头发带有运动模糊",
      "第二格：特写眨眼，脸上带有浓重的 Pro-Mist 柔光光晕",
      "第三格：坐在地板上，相机倾斜，因移动而产生轻微的双重曝光效果",
      "第四格：用手遮住嘴巴，害羞而调情"
    ]
  },
  "background": {
    "setting": "个人卧室，略显凌乱但舒适",
    "lighting_elements": "温暖的床头灯、小彩灯或霓虹灯反射，由于相机摇摄运动而产生光轨（焦外光斑条纹）",
    "ambiance": "黑暗的房间被刺眼但柔和的闪光灯照亮"
  },
  "photography": {
    "technique": "慢速快门同步闪光（拖影快门）",
    "filter": "{argument name=\"diffusion filter\" default=\"Black Pro-Mist 1/4 filter\"}（在高光周围产生光晕）",
    "focus": "柔焦，为艺术效果略微失焦",
    "color_grading": "复古胶片（{argument name=\"film stock\" default=\"Kodak Portra 800 or Cinestill 800T\"}），偏绿的阴影，温暖发光的高光",
    "texture": "浓重的胶片颗粒感，噪点，不完美，模拟感"
  },
  "constraints": {
    "layout": "2x2 网格拼贴",
    "composition": "相机摇摄效果应使背景灯光水平或旋转拖曳，而闪光灯则相对清晰地定格面部。"
  }
}

