    },
    "full_body": {
      "type": "ip-adapter-plus",
      "enabled": false,
      "weight": 0,
      "source": "uploaded_image"
    }
  },
  "prompt": "Use the uploaded image strictly as IDENTITY reference only. Preserve facial features, skin tone, face shape, eye structure, nose, lips, jawline, hairstyle type, and body proportions exactly. Do NOT copy pose, posture, camera angle, lighting, background, or clothing from the reference.\n\nUltra-realistic full-body studio fashion portrait. Subject stands centered.\n\nWardrobe (must match exactly): cropped light-wash turquoise denim jacket with distressed seams and frayed edges, exposed midriff and visible navel, dark navy-blue skinny jeans with subtle worn texture and copper rivets, round yellow-orange tinted aviator sunglasses with thin metal frame.\n\nPose (select ONE randomly per generation, do NOT mix):\nA) Arms raised behind head, hands tying hair, confident serious expression.\nB) Both hands loosely crossed in front, leaning slightly forward, subtle soft smile.\nC) One hand on hip, other hand holding jacket collar, confident attitude expression.\n\nHair styled naturally to fit pose. Minimal makeup, realistic skin texture.\n\nBackground: solid matte peach-beige studio backdrop.\nLighting: soft diffused front light, gentle shadows.\nCamera: full-body, straight-on, eye-level, 50mm look, shallow depth.\n\nColor palette: warm peach-beige background, cool turquoise jacket, deep navy jeans, amber-yellow glasses, natural warm skin tones.\nColor grading: soft warm cinematic, subtle teal-orange, muted highlights, low contrast, matte finish, film softness.\n\nStyle: high-end fashion editorial, Vogue studio shoot.\nQuality: ultra-detailed, photorealistic, 8K, sharp focus, professional photography.",
  "negative_prompt": "multiple poses, mixed poses, wrong clothing, missing sunglasses, hoodie, t-shirt, dress, skirt, shorts, copied reference pose, bad anatomy, extra limbs, distorted hands, plastic skin, heavy makeup, cartoon, anime, illustration, watermark, logo, blur, noise, low quality, oversaturated, overprocessed",
  "steps": 35,
  "cfg_scale": 7.5,
  "sampler": "DPM++ 2M Karras",
  "width": 1024,
  "height": 1536,
  "clip_skip": 2
}

