{
  "subject": {
    "primary": "A stunning young western woman with long platinum blonde hair in a high messy ponytail, wearing clear pink-tinted round glasses, large gold hoop earrings, dramatic makeup with glossy lips, sitting thoughtfully at an outdoor café table in a narrow charming European alleyway at night during Christmas season, pensive expression with finger touching lips.",
    "clothing": "Ultra-cozy luxurious winter outfit: oversized fluffy brown faux-fur coat draped over shoulders, cropped striped button-up shirt, loose brown tie, high-waisted dark denim mini skirt, thick thigh-high socks implied, black leather boots, red Jacquemus-style mini handbag on the table."
  },
  "environment": {
    "setting": "Narrow charming European alleyway at night during Christmas season.",
    "decorations": "Warm golden string lights, large Christmas wreaths with gold baubles and pinecones hanging above, festive holiday decorations, glowing orange patio heaters.",
    "architecture": "Old stone buildings with wooden shutters and wrought iron balconies in background."
  },
  "mood": {
    "expression": "Pensive, thoughtful",
    "pose": "Finger touching lips, sitting at café table",
    "atmosphere": "Romantic, cozy, cinematic, soft bokeh lights"
  },
  "visual_style": {
    "detail": "Highly detailed, photorealistic fashion portrait",
    "lighting": "Warm lighting",
    "depth_of_field": "Shallow depth of field",
    "camera": "Shot on Fujifilm Superia 400, 85mm lens"
  },
  "notes": {
    "facial_features": "Use the same face from the reference image without changing facial features."
  }
}

