promptEn:
{
  "style": "Jirai Kei / Cosplay Editorial",
  "framing": {
    "shot_type": "MCU (Vertical)",
    "camera_angle": "Eye Level",
    "camera_position": "Frontal, vertical stack layout"
  },
  "aspect_ratio": "9:16 (Vertical)",
  "subject": {
    "description": "Young woman with pale skin, Hime cut black hair, red ribbon, Jirai Kei makeup",
    "identity_lock": "Pale skin, red eyes, pouty expression"
  },
  "clothing": {
    "garment": "Plaid bustier and fuzzy cardigan",
    "construction_details": "Grey/black plaid structured camisole, white thick textured knit cardigan",
    "what_it_reveals": "Cardigan is worn off-the-shoulder revealing collarbones and bustier straps"
  },
  "visible_body": {
    "area": "Face, neck, collarbones, hands",
    "size_descriptor": "Petite, delicate",
    "what_is_seen": "Porcelain skin texture, stylized red eye makeup",
    "visibility_level": "High detail on face and makeup"
  },
  "camera": {
    "body": "Sony A7R V",
    "lens": "35mm f/1.4 GM",
    "aperture": "f/2.8",
    "fallback_style": "High-res cosplay photography"
  },
  "lighting": {
    "type": "Indoor Diffuse",
    "direction": "Overhead/Frontal",
    "quality": "Soft, high-key"
  },
  "environment": "Themed collaboration cafe, wall posters with anime art, leather booth",
  "focal_point": {
    "primary": "Subject's face and spoon pose",
    "declaration": "THE COMPOSITION STACKS THE FOOD IN FOREGROUND AND SUBJECT ABOVE"
  },
  "composition": {
    "camera_angle": "Eye level",
    "crop": "Vertical 9:16 crop: Table food at bottom, subject in center/top",
    "pose": "Holding black spoon near cheek, direct gaze"
  },
  "props": {
    "food": "Tonkatsu cutlet, shredded cabbage, rice bowl (Lower Third)",
    "decor": "Paper flag pick, Kuro Games poster (Background)"
  },
  "negative_prompt": "horizontal, landscape, wide shot, western makeup, tanned skin, blonde hair, messy hair, outdoor, dark lighting, low resolution, bad anatomy, deformed hands, missing spoon, wrong food, burger, pizza, casual t-shirt, fully worn cardigan, zip-up hoodie, bright smile",
  "full_prompt": "Candid editorial cosplay photograph in the 'Jirai Kei' (Landmine Girl) aesthetic, captured inside a themed collaboration cafe. Shot on Sony A7R V with 35mm f/1.4 GM lens at f/2.8. Lighting is bright, high-key diffuse indoor ambiance. 9:16 vertical format. The subject is a young woman with a pale, porcelain complexion and jet-black hair styled in a precise Hime cut. A long, silky crimson red ribbon is tied in a bow on the right side of her head. Makeup features red-tinted contact lenses, reddish-pink eyeshadow, high blush, and glossy lips pursed in a soft pout. She wears a structured grey and black plaid bustier camisole top. Over this, she wears a thick, white, fuzzy textured cardigan—THE CARDIGAN IS WORN LOOSELY OFF-THE-SHOULDER. A silver chain necklace with a dark red heart pendant rests against her skin. The composition is vertical, stacking elements for depth. She poses holding a black ceramic soup spoon in her left hand, raised playfully near her left cheek. The lower third features a Japanese set meal: crispy fried Tonkatsu with cabbage and a character-themed pick. Background shows cafe booth and wall poster with 'Chibi' anime character."
}

