    "visibility_level": "面部与妆容高度细节化"
  },
  "camera": {
    "body": "Sony A7R V",
    "lens": "35mm f/1.4 GM",
    "aperture": "f/2.8",
    "fallback_style": "高分辨率 Cosplay 摄影"
  },
  "lighting": {
    "type": "室内漫射",
    "direction": "顶部/正面",
    "quality": "柔和，高调"
  },
  "environment": "主题联名咖啡馆，墙面动漫海报，皮质卡座",
  "focal_point": {
    "primary": "主体面部与勺子姿态",
    "declaration": "构图将食物堆叠于前景，主体置于上层"
  },
  "composition": {
    "camera_angle": "平视",
    "crop": "竖向 9:16 裁剪：桌面食物在底部，主体居中/上层",
    "pose": "手持黑色勺子贴近脸颊，直视镜头"
  },
  "props": {
    "food": "炸猪排、切丝卷心菜、米饭（下三分之一处）",
    "decor": "纸旗签、Kuro Games 海报（背景）"
  },
  "negative_prompt": "横向、风景、广角、西式妆容、小麦肤色、金发、凌乱发、户外、暗光、低分辨率、解剖错误、手部畸形、缺失勺子、错误食物、汉堡、披萨、休闲 T 恤、完整穿着开衫、拉链卫衣、灿烂笑容",
  "full_prompt": "在主题联名咖啡馆内拍摄的‘地雷系’风格随性的 Cosplay 时尚写真。使用 Sony A7R V 机身与 35mm f/1.4 GM 镜头，光圈 f/2.8。光线为明亮、高调的漫射室内氛围。9:16 竖屏格式。主体为一位肌肤苍白、如瓷般细腻的年轻女子，乌黑长发修剪成精准的姬切。一条光滑的深红丝带在头部右侧打成蝴蝶结。妆容采用红色美瞳、红粉色眼影、高饱和腮红与嘟起的亮泽唇。她身穿结构感灰黑格纹抹胸吊带外罩厚实质感的白色毛绒开衫——开衫松散滑落肩头。一条银链配暗红色心形吊坠轻贴肌肤。竖向构图层层堆叠营造景深。她左手举起黑色陶瓷汤勺俏皮贴近左颊。画面下三分之一为日式套餐：酥脆炸猪排配卷心菜与角色主题小旗签。背景可见卡座与墙上‘Chibi’动漫角色海报。"
}

