{
  "reference": {
    "type": "image",
    "usage": "Use the uploaded image as the sole source of truth. Do not assume garment type beyond what is visually observable."
  },
  "scene": {
    "description": "Minimal, premium fashion presentation layout inspired by high-end industrial design documentation and contemporary fashion lookbooks.",
    "background": "Pure white, clean, distraction-free"
  },
  "subject": {
    "primary": "A young, stylish, attractive model wearing the garment",
    "role": "The model serves only as a human form to display the clothing; visual analysis and annotations apply strictly to the garment itself",
    "pose": "Neutral, relaxed standing pose that clearly presents garment structure and silhouette",
    "expression": "Calm, natural, non-distracting"
  },
  "layout": {
    "top_left": {
      "content": "Brand name",
      "style": "Modern sans-serif typography, subtle, elegant"
    },
    "left_column": {
      "content": "Multiple auxiliary garment views",
      "views": [
        "Front view on model",
        "Side view on model",
        "Rear view on model",
        "Detail close-up view of fabric, collar, zipper, cuff, or seam"
      ],
      "arrangement": "Vertically stacked, evenly spaced, aligned"
    },
    "right_section": {
      "content": "Main hero garment presentation on model",
      "style": "Large, dominant, photorealistic",
      "lighting": "Soft studio lighting optimized for fabric texture and silhouette clarity",
      "materials": "Visually accurate to the uploaded garment, including fabric weight, stitching, and surface finish"
    }
  },
  "annotations": {
    "analysis_phase": [
      "Visually analyze the garment to identify distinct external components and construction details",
      "Identify fabric panels, closures, edges, seams, layers, and surface treatments",
      "Ignore the model's anatomy except where it affects garment drape or structure"
    ],
    "binding_rules": [
      "Each annotation line must point to one clearly visible garment component",
      "Each label must describe exactly what that garment component is and its visually implied function",
      "No label may describe the model's body or rely on fashion trend terminology",
      "One line equals one garment component equals one explanation"
    ],
    "line_style": {
      "type": "Hairline-thin vector lines",
      "color": "Neutral light gray",
      "termination": "Exact contact point on the referenced garment component"
    },
    "labels": {
      "content_rules": [
        "Use neutral, descriptive garment construction terms (e.g. outer shell panel, collar structure, closure opening, sleeve panel, seam line, cuff edge)",
        "Mention fabric or material only if visually identifiable",
        "Mention function only if structurally implied (e.g. closure, coverage, adjustment)",
        "Avoid marketing, trend, or brand storytelling language"
      ],
      "placement_rules": [
        "Place text outside the garment silhouette",
        "Maintain consistent spacing",
        "Avoid overlaps",
        "Align labels for technical clarity"
      ],
      "tone": "Factual, precise, non-marketing",
      "typography": "Minimal technical sans-serif"
    }
  },
  "visual_style": {
    "aesthetic": "Modern Scandinavian fashion documentation with industrial design influence",
    "mood": "Calm, precise, professional",
    "color_palette": "Neutral and restrained, allowing garment color to stand out"
  },
  "rendering": {
    "quality": "Ultra-high resolution",
    "shadows": "Soft and realistic, emphasizing garment drape and volume",
    "accuracy": "Exact garment proportions, stitching alignment, and fabric behavior fidelity"
  },
  "rules": {
    "do_not": [
      "Assume garment category beyond visible structure",
      "Describe the model as the product",
      "Hallucinate hidden layers or internal padding",
      "Use generic fashion marketing language",
      "Mismatch labels and garment components",
      "Decorate annotation lines"
    ],
    "focus_on": [
      "Visual truth of the garment",
      "Construction-level understanding",
      "Component-level garment analysis",
      "Professional fashion design documentation"
    ]
  }
}

