    },
    "clothing_anchor": {
      "source": "与参考照片完全一致",
      "strictness": "关键",
      "instruction": "款式、颜色、材质与合身度必须完全对应原始照片，不得风格化。"
    }
  },
  "subject_details": {
    "expression": "严肃、紧张、专注",
    "gaze": "视线离开镜头，望向镜头上方空间",
    "universality": "不论性别均适用的光线与角度"
  },
  "composition": {
    "background": "饱和的橙红纯色背景，平滑强烈渐变，无图案，营造“炽热”氛围",
    "camera_angle": "低位仰拍（从下方往上拍）以营造支配感",
    "framing": "中近景，强调面部与肩部"
  },
  "lighting": {
    "palette": "以明亮橙色与深红色调为主",
    "key_light": "强方向性光源，深戏剧性阴影（明暗对比），突出面部结构",
    "backlight": "极具表现力的强力轮廓光或色晕，将主体与背景分离",
    "mood": "神秘、紧张、高对比"
  },
  "technical_specs": {
    "style": "摄影级真实，高细节",
    "focus": "面部锐利对焦，背景为平滑渐变",
    "texture_quality": "保留自然毛孔与皮肤纹理"
  },
  "combined_prompt_text": "世界顶级编辑肖像，戏剧性棚光，英雄气质。[参考照片身份保持]：面部特征、肤色、发型完全不变。[服装完全匹配]：不改动合身度与材质。表情：严肃、紧张、专注，朝上方远方凝视。背景：饱和橙红纯色，平滑强烈渐变，炽热氛围。摄影角度：低位仰拍制造支配感。构图：中近景。灯光：明亮橙与深红色调，强方向性明暗对比主光，强力轮廓光分离主体与背景。技术：摄影级真实、高细节，面部锐利对焦，保留自然皮肤纹理与毛孔。"
}

