  }
}

promptCh:
{
  "portrait_prompt": {
    "subject": "基于<用户肖像>，一位年轻女子坐在被斑驳积雪覆盖的黑色出租车引擎盖上。她穿着已上传的服装。她的姿势因透视而动态扭曲：双腿向前伸展，右手径直伸向相机镜头，产生极度透视缩短效果，手部在前景中显得巨大。",
    "composition": "超广角鱼眼镜头（约 10mm-12mm），俯拍高角度。极端透视畸变。主体伸出的手占据右前景，引导视线至中央面部。汽车引擎盖填满画面底部。",
    "camera_angle": "高角度，贴近主体的手以夸张鱼眼效果。",
    "lighting": "明亮清爽的自然日光。积雪充当巨型反光板（补光），均匀照亮主体面部。高对比度光线，细节锐利。",
    "color_palette": "鲜艳饱和的原色（黄色衣袖、红色短裤、蓝色马甲/天空）在高对比黑色车身与白雪映衬下跃动。阴影处呈冷调日光色，天空湛蓝。",
