promptEn:
{
  "portrait_prompt": {
    "subject": "Based on <User Portrait>, a young woman crouching on a park lawn, posing playfully. She is holding two fresh red tomatoes against her cheeks with both hands, elbows resting on her knees. She wears a white oversized t-shirt dress, white knee-high socks, and light blue sneakers. Her hair is styled in loose, slightly messy braids. A bright blue shoulder bag hangs by her side. In the background, there is a park scenery with trees and benches.",
    "composition": "Full body shot, wide angle (approx 35mm), extremely low angle perspective looking up at the subject to frame her against the sky, moderate depth of field (f/5.6) keeping the subject sharp while softening the background trees.",
    "camera_angle": "Extremely low angle shot (ground level view), tilting upwards to capture the subject and the vast blue sky behind her.",
    "lighting": "Bright, direct natural sunlight (high noon or early afternoon), high-key lighting, creating a fresh and airy look with distinct but not harsh shadows, illuminating the face clearly.",
    "color_palette": "Fujifilm Nostalgic Negative inspired color grading, warm golden highlights, reddish shadows, rich midtones, cinematic backlight glow, subtle halation, soft film grain. Dominant sky blues, grassy greens, clean whites, and the pop of red from the tomatoes. Slightly overexposed highlights for a dreamy, summery feel.",
    "mood": "Fresh, summery, playful, candid, youthful, lifestyle aesthetic, bright and cheerful.",
    "negative_prompt": "dark, gloomy, studio lighting, heavy makeup, formal wear, night, indoor, blurry, low resolution, distorted hands, bad anatomy, missing fingers, extra limbs, watermark, text, muted colors, cold clinical grading, harsh contrast, crushed shadows, excessive sharpness, heavy saturation, HDR."
  }
}

