    "photographic_style": {
      "aesthetic": "Cozy Home Snapshot, Soft Flash Aesthetics, Authentic Lifestyle",
      "camera_angle": "High-angle shot with a wide lens (28mm) to accentuate the playful leg-up pose and capture the surrounding plushies.",
      "lighting": "Soft direct flash mixed with warm bedroom ambient light (lamp light), creating a creamy, inviting tone without harshness.",
      "color_grading": "Fujifilm Classic Negative (NC) style; slightly desaturated greens, warm skin tones, and soft highlights to emphasize the satin texture.",
      "film_grain": "Subtle grain for a natural, unpolished look."
    },
    "pose_reference": "Reclining on the sofa, kicking one leg up towards the camera (foreshortening), hand reaching forward or framing the face playfully. Spontaneous and energetic but relaxed.",
