promptEn:
{
  "scene_1_mickey_minnie": {
    "prompt": "A hyperrealistic, editorial fashion photograph in a studio setting. A real human model with a natural, confident expression and a preserved face stands between giant, photorealistic 3D animated characters, Mickey Mouse and Minnie Mouse. The human wears a chunky knitted sweater in pastel pink and cream tones, high-waisted light blue jeans, and clean white minimalist sneakers. Mickey poses with his classic cheerful stance, showing realistic gloves, fabric textures, and slight scuff details. Minnie stands slightly to the side with a playful tilt, wearing her iconic polka dot dress and bow, rendered with detailed fabric and subtle wear. The background is a clean split studio backdrop of soft sky blue and light peach. Soft, professional studio lighting highlights textures of knitwear, denim, and animated fabrics, preserving their identity. 3/4 body framing, magazine-cover quality."
  },
  "scene_2_tyranitar": {
    "prompt": "A hyperrealistic, premium fashion photograph in a studio setting. A real human model with a confident, defiant expression and a preserved face stands next to a massive, imposing 3D animated Tyranitar, rendered in photorealistic quality. The human wears a dark forest green knitted sweater, black slim-fit jeans, and white sneakers, posing with their body slightly angled toward the camera. Tyranitar towers with textured, rocky green skin, sharp claws, and a realistic muscular frame, its tail curved behind. The background is a muted slate gray studio backdrop with subtle green ambient light accents. Soft but contrast-rich studio lighting defines textures and mass. 3/4 body framing, editorial aesthetic."
  },
  "scene_3_iron_man_captain_marvel": {
    "prompt": "A modern, urban, premium fashion photograph in a studio setting. A real human model with a cool, composed expression and a preserved face stands between near-human scale photorealistic 3D animated renders of Iron Man and Captain Marvel. The human wears a knitted sweater with metallic red and deep blue accents, high-waisted dark jeans, and clean white sneakers. Iron Man stands casually in his armor, showing realistic metal textures, reflections, and glowing repulsors. Captain Marvel stands confidently on the other side, rendered with photorealistic suit textures, flowing hair, and a determined expression. The background is deep concrete gray with subtle gold and red light accents. Soft studio lighting with defined rim light separates all figures. 3/4 framing, modern editorial look."
  },
  "scene_4_studio_groot": {
    "prompt": "A relaxed, premium fashion portrait in a studio setting. A real human model with a confident, charming smile and a preserved face rests an arm naturally on the shoulder of a true human scale photorealistic 3D animated character, Groot. The human wears a soft beige knitted sweater, high-waisted dark jeans, and clean white sneakers. Groot, rendered with hyperrealistic wooden textures, moss accents, and expressive eyes, stands with a calm, friendly posture. The background is a clean warm taupe studio backdrop. Soft studio lighting with subtle rim light enhances the textures of wood and clothing and creates a natural chemistry. 3/4 framing, high-end fashion editorial."
  }
}

promptCh:
{
  "scene_1_mickey_minnie": {
    "prompt": "一张超现实、杂志感的时尚摄影，置景于摄影棚。一位真实人类模特带着自然、自信的面部表情，被保留原貌，站在巨大的、写实级3D动画角色米老鼠与米妮鼠之间。人类穿着一件粗针织毛衣， pastel 粉与奶油色调，高腰浅蓝色牛仔裤，干净白色极简运动鞋。米老鼠摆出其经典欢快姿势，展示真实质感手套、布料纹理与轻微磨损细节。米妮站在稍侧，带着俏皮倾斜，穿着标志性波点裙与蝴蝶结，以精细布料与轻微磨损呈现。背景为干净分割的摄影棚背景，柔和天蓝与浅桃色。柔和、专业棚拍光线突出针织、牛仔与动画布料的纹理，同时保留其身份。3/4 身框，杂志封面级品质。"
  },
  "scene_2_tyranitar": {
    "prompt": "一张超现实、高端时尚摄影，置景于摄影棚。一位真实人类模特带着自信、桀骜的表情，面部保持原貌，站在一只巨大、威压感十足的写实级3D动画班吉拉旁。人类身着深林绿色针织毛衣、黑色修身牛仔裤与白色运动鞋，身体微向镜头倾斜摆姿。班吉拉高耸，拥有纹理丰富的岩石绿皮肤、锋利爪子与真实肌肉轮廓，尾巴在后方弯曲。背景为柔和石板灰摄影棚背景，辅以微妙绿色环境光点缀。柔和但高对比棚光清晰定义纹理与体量。3/4 身框，杂志美学。"
  },
  "scene_3_iron_man_captain_marvel": {
    "prompt": "一张现代、都市、高端时尚摄影，置景于摄影棚。一位真实人类模特带着冷静、镇定的表情，面部保持原貌，站在接近真人比例的写实级3D动画钢铁侠与惊奇队长之间。人类穿着一件金属红与深蓝点缀的针织毛衣、高腰深色牛仔裤与干净白色运动鞋。钢铁侠在其装甲中随意站立，呈现真实金属纹理、反射与发光掌心炮。惊奇队长自信立于另一侧，以写实级战服纹理、飘逸秀发与坚毅神情呈现。背景为深混凝土灰，辅以微妙金与红光点缀。柔和棚拍光线配清晰边缘光分离所有人物。3/4 框，现代杂志外观。"
  },
  "scene_4_studio_groot": {
    "prompt": "一张轻松、高端时尚肖像，置景于摄影棚。一位真实人类模特带着自信、迷人的微笑，面部保持原貌，自然地将手臂搭在真人比例的写实级3D动画角色格鲁特肩上。人类身着柔软米色针织毛衣、高腰深色牛仔裤与干净白色运动鞋。格鲁特以超现实木质纹理、苔藓点缀与富有表现力的双眼呈现，站姿平静友好。背景为干净温暖的灰褐色摄影棚背景。柔和棚拍光线与微妙边缘光强化木材与服装纹理，营造自然化学反应。3/4 框，高端时尚杂志。"
  }
}

