promptEn:
{
  "project_name": "Winter_Playful_Fall_Dynamic_Impact",
  "visual_narrative": {
    "subject": {
      "description": "A trendy young woman in the middle of a playful, natural fall backwards into deep snow. She is looking up at the camera with a cheeky, natural wink and a bright smile.",
      "action": "The pose is dynamic and candid. As she lands/falls, her body displaces a massive burst of snow. One hand reaches eagerly towards the camera lens (creating extreme perspective foreshortening), while the other arm or elbows hit the snow, sending chunks of white powder flying upwards.",
      "reference_slots": {
        "face_detail": "[User Portrait Image: Natural Smile + Wink]",
        "apparel_detail": "[User Apparel: Trendy Winter Fashion - e.g., Silver/White Glossy Puffer, Fur Accessories, Colorful Scarf]",
        "pose_control": "[ControlNet: Depth/Canny - Falling Backward + Reaching Hand Perspective]"
      }
    },
    "environment": {
      "setting": "A sunlit snowfield with a deep blue sky backdrop. The perspective makes the sky feel expansive.",
      "atmosphere": "Explosive and airy. The air is filled with flying snow clumps and fine powder mist caused by the impact of the fall, creating a 'frozen in time' effect.",
      "sky": "Vibrant, cloudless azure blue."
    }
  },
  "technical_parameters": {
    "camera": {
      "lens": "18mm Wide-Angle Prime",
      "aperture": "f/2.8",
      "perspective": "First-Person POV (Point of View). The camera looks down as the subject falls away from it, with the hand coming close to the lens to emphasize depth.",
      "shutter_speed": "1/4000s (To freeze the individual snow clumps and hair motion sharpness)"
    },
    "lighting": {
      "type": "High-Key Sunlight",
      "quality": "Crystal clear and transparent. The sunlight hits the flying snow particles, turning them into sparkling bokeh. The snow acts as a fill light, making the skin look translucent and fair.",
      "contrast": "Medium-High contrast on textures, but low contrast on skin tones."
    },
    "color_grading": {
      "style": "Fujifilm Classic Negative (NC) - Vibrant & Airy",
      "palette": "Clean White, Deep Sky Blue, Vibrant Fashion Colors, Rosy Skin Tones.",
      "tone": "Bright, open shadows, slightly blown-out highlights in the snow for that 'blindingly bright winter' feel."
    }
  },
  "prompt_construction": {
    "positive": "masterpiece, [User Portrait], playful falling backwards into snow, candid shot, dynamic motion, winking one eye, natural bright smile, hand reaching towards camera, extreme foreshortening, touching the lens, massive snow splash, snow powder flying into air, exploding snow, trendy winter fashion, glossy puffer jacket, sunny winter day, clear blue sky, high key lighting, transparent skin, airy atmosphere, sparkling ice crystals, frozen motion, sharp focus on eye, 8k, Fujifilm color science.",
    "negative": "stiff pose, staged, fake expression, painful expression, dark, gloomy, motion blur on face, bad anatomy, distorted hands, missing fingers, extra fingers, ugly face, low resolution, muddy snow, grey sky, studio lighting, flat image."
  }
}

promptCh:
{
  "project_name": "冬日戏雪后仰动感瞬间",
  "visual_narrative": {
    "subject": {
      "description": "一位时髦的年轻女子正自然俏皮地后仰跌入厚雪中。她抬头看向镜头，带着调皮的天然眨眼和灿烂笑容。",
      "action": "姿势动感且抓拍。在她落地/后仰瞬间，身体激起巨大雪浪。一只手急切伸向镜头（产生极端透视缩短），另一臂或肘部击中雪地，溅起白色雪尘向上飞扬。",
      "reference_slots": {
        "face_detail": "[用户人像图像：自然微笑+眨眼]",
        "apparel_detail": "[用户服装：时髦冬装——如银/白色亮面羽绒、毛皮配饰、亮色围巾]",
        "pose_control": "[ControlNet：深度/边缘——后仰+伸手透视]"
      }
    },
    "environment": {
      "setting": "阳光照耀的雪原，深蓝天空背景。视角让天空显得广阔无垠。",
