promptEn:
{
  "variables": {
    "CITY_NAME": "Chengdu"
  },
  "image_specs": {
    "aspect_ratio": "4:5",
    "resolution": "2048x2560",
    "quality": "ultra",
    "style_strength": 0.8,
    "detail_level": "high",
    "sharpen": "medium"
  },
  "prompt": {
    "master_visual_brief": "A high-energy Y2K-inspired editorial collage poster with a strong paper-cut and magazine print aesthetic. The entire image has a tactile paper texture with visible cut edges and layered depth. The theme centers around the city {{CITY_NAME}}. All visual elements, including background imagery, stickers, symbols, typography, and graphic decorations, are culturally and visually inspired by {{CITY_NAME}}. The composition follows a fashion magazine cover logic with dense but controlled information, playful energy, and strong visual hierarchy. The character is designed as a dominant half-body portrait occupying most of the poster.",
    "photography_and_character": "Character: a randomly generated young woman aged approximately 18–25. She is fashionable, attractive, and trendy, with no fixed hairstyle, hair color, facial features, or makeup. Her appearance varies naturally but always remains stylish and visually appealing. Fashion style is Y2K-inspired street fashion with playful silhouettes, layered styling, and trendy colors. Framing is a strict half-body portrait: the image is cropped at the waist or slightly above, and the lower body is not visible at all. Only the upper torso, shoulders, neck, and head are shown. Pose and gesture: the character performs a randomly selected Y2K-style dynamic pose with strong tension and attitude, including expressive arm extensions, angular elbow bends, asymmetrical shoulder twists, or forward-reaching gestures. Body language remains bold, confident, and energetic. Facial expression: the expression is slightly playful and friendly, with a hint of cuteness layered on top of confidence. Subtle smiles, softly open lips, bright eyes, or a relaxed playful look are allowed, while the overall attitude remains fashion-forward and dynamic rather than cute-only.",
    "camera_and_lighting": "Editorial portrait framing with a wide-angle look at close distance, optimized for half-body composition. The camera captures only the upper torso and head, with the lower body fully cropped out of frame. Perspective supports dynamic Y2K poses without distorting facial proportions. Lighting is soft, even, and magazine-style, avoiding harsh shadows. The subject is intended to be cut out and integrated into a paper collage rather than rendered as pure realism.",
    "graphic_design_layout": "Center-focused editorial collage layout. At the top, the city name '{{CITY_NAME}}' appears as the main headline in bold uppercase geometric sans-serif letters. Each letter is placed on an individual colored paper rectangle and arranged in a slight arc. The large half-body character overlaps and partially covers the headline and nearby graphic elements, creating a break-the-frame effect. Surrounding the character are floating paper stickers, speech bubbles, and cut-out graphics inspired by {{CITY_NAME}} culture, including local food, landmarks, symbols, street signs, and iconic objects. The bottom section features a full-width magazine-style collage footer composed of layered paper strips, bold button-style typography, small editorial text blocks, and thumbnail-style graphics.",
    "background_system": "The background is a black-and-white or desaturated urban street scene from {{CITY_NAME}}, such as crowds, architecture, or city textures. Background contrast is reduced and softened with grain so it supports the composition without competing with the main subject. The background is partially obscured by the large half-body character and collage elements and maintains a printed-paper appearance rather than photographic realism.",
    "materials_and_textures": "A consistent paper-based aesthetic across the entire image. Visible paper grain, halftone dots, print noise, and slight ink bleed. All elements appear as physical paper cut-outs layered together. Edges are imperfect and tactile. Stickers, typography, and characters cast subtle shadows to suggest layered depth. No glossy, metallic, or digital materials are present.",
    "composition_and_balance": "Clear and stable visual hierarchy: top city headline '{{CITY_NAME}}', central half-body character (upper torso only), dynamic Y2K-style pose with slightly playful facial expression, surrounding city-themed stickers, and bottom magazine-style collage footer. Strong overlaps between character, typography, and stickers create depth while preserving the established layout."
  },
  "constraints": {
    "must_include": \[
      "City name headline using {{CITY_NAME}}",
      "Strict half-body portrait (waist-up only)",
      "Lower body completely cropped out",
      "Y2K-style dynamic pose with strong tension",
      "Playful but controlled facial expression",
      "Paper collage and cut-out magazine aesthetic",
      "City-specific background and stickers related to {{CITY_NAME}}",
      "Full-width magazine-style collage footer",
      "Visible paper texture and layered depth" \
    ],
    "must_avoid": \[
      "Full-body view",
      "Visible legs, knees, thighs, or feet",
      "Neutral or stiff poses",
      "Overly cute or childish expressions",
      "Sexualized expressions or gestures",
      "Grotesque facial distortion",
      "Minimalist or empty layouts",
      "Glossy digital or 3D materials" \
    ]
  },
  "negative_prompt": "full body, legs visible, knees, thighs, feet, stiff pose, neutral posture, childish expression, exaggerated cute face, sexualized expression, blurry face, deformed hands, extra fingers, bad anatomy, grotesque distortion, minimalist layout, flat image, hyper-realistic photography, glossy surfaces, plastic skin, dull colors, watermark, logo, unreadable text",
  "typography_rules": {
    "headline": {
      "text": "{{CITY_NAME}}",
      "font_style": "bold geometric sans-serif, uppercase",
      "treatment": "each letter on a separate colored paper rectangle, slightly arched, subtle shadow",
      "material": "printed paper cut-out"
    },
    "supporting_text": {
      "style": "editorial magazine blocks, playful sticker captions, speech bubbles",
      "material": "paper-based printed texture"
    }
  },
  "rendering_notes": {
    "depth_layers": "background city paper layer -> mid-ground half-body character -> foreground dynamic pose, expressive face, stickers, and typography",
    "print_feel": "strong magazine print texture with halftone dots, paper grain, and slight ink bleed",
    "edge_treatment": "clearly visible imperfect cut paper edges"
  }
}

promptCh:
{
  "变量": {
    城市名称：成都
  },
  "image_specs": {
    "aspect_ratio": "4:5",
    "resolution": "2048x2560",
    "quality": "ultra",
    "style_strength": 0.8,
    "detail_level": "high",
    "sharpen": "medium"
  },
  “提示词”： {
    “视觉设计概要”： “这是一张充满活力、灵感源自Y2K时代的拼贴海报，
    具有强烈的剪纸和杂志印刷美感。整幅图像呈现出触感丰富的纸张纹理，
    可见的切割边缘和层次感。主题围绕着城市{
      {
        CITY_NAME
      }
    }展开。所有视觉元素，
    包括背景图像、贴纸、符号、字体和图形装饰，
    都从文化和视觉上汲取灵感，
    源自城市{
      {
        CITY_NAME
      }
    } 。构图遵循时尚杂志封面的逻辑，
    信息丰富但控制得当，
    充满活力，
    并具有清晰的视觉层次。人物被设计成占据海报大部分空间的半身肖像。” “摄影与人物”： “人物：一位随机生成的年轻女性，
    年龄在18至25岁之间。她时尚、迷人、潮流，
    没有固定的发型、发色、五官或妆容。她的外貌自然变化，
    但始终保持时尚和视觉吸引力。时尚风格是受Y2K时代启发的街头时尚。”俏皮的轮廓、层次丰富的造型和潮流的色彩。构图采用严格的半身像：画面裁剪至腰部或略高于腰部，
    下半身完全不可见。仅展现上半身、肩膀、颈部和头部。姿势和手势：人物摆出随机选择的Y2K风格动态姿势，
    充满张力和态度，
    包括富有表现力的手臂伸展、肘部角度弯曲、不对称的肩部扭转或向前伸展的动作。肢体语言大胆、自信且充满活力。面部表情：表情略带俏皮和友好，
    在自信之上又增添了一丝可爱。允许有淡淡的微笑、微微张开的嘴唇、明亮的眼神或轻松俏皮的表情，
    整体风格保持时尚前卫和动感，
    而非仅仅可爱。“相机和灯光”：“采用广角镜头近距离拍摄的编辑人像构图，
    针对半身像进行了优化。相机仅拍摄上半身和头部，
    下半身不可见。”人物身体完全裁剪出画面之外。透视效果支持动态的千禧年风格姿势，
    且不会扭曲面部比例。光线柔和均匀，
    采用杂志风格，
    避免了生硬的阴影。人物旨在被剪裁并融入纸质拼贴画中，
    而非以纯粹的写实手法呈现。平面设计布局：以中心为焦点的编辑拼贴画布局。顶部，
    城市名称“ {
      {
        城市名称
      }
    } ”以粗体大写几何无衬线字体作为主标题。每个字母都放置在单独的彩色纸质矩形上，
    并呈略微弧形排列。较大的半身人物与标题和附近的图形元素重叠并部分覆盖，
    营造出一种打破画面框架的效果。人物周围环绕着漂浮的纸质贴纸、对话气泡和剪纸图形，
    其灵感来自{
      {
        城市名称
      }
    }的文化，
    包括当地美食、地标、符号、路标和标志性物品。底部部分是一个由多层纸张组成的全宽杂志风格拼贴画页脚。条状文字、醒目的按钮式字体、小型编辑文本块和缩略图式图形。”,
    “背景系统”: “背景是来自{
      {
        城市名称
      }
    }的黑白或低饱和度城市街景，
    例如人群、建筑或城市纹理。背景对比度降低，
    并添加了颗粒感以柔化画面，
    从而在不干扰主体的情况下支持构图。背景部分被大型半身人物和拼贴元素遮挡，
    保持了印刷纸的外观，
    而非照片的真实感。”,
    “材质与纹理”: “整个图像保持一致的纸质美学。可见的纸张纹理、半色调网点、印刷噪点和轻微的墨迹晕染。所有元素都像是层叠在一起的实体纸片。边缘不完美且触感明显。贴纸、字体和人物投射出微妙的阴影，
    暗示出层次感。没有光泽、金属或数字材质。”,
    “构图与平衡”: “清晰稳定的视觉层次：顶部城市标题“ {
      {
        城市名称
      }
    } ”，
    中央半身人物（仅上半身），
    动态的千禧年风格姿势，
    略带俏皮的面部表情，
    周围环绕着城市主题贴纸，
    底部是杂志风格的拼贴页脚。人物、字体和贴纸之间的强烈重叠在保持既定布局的同时，
    营造出层次感。
  },
  "约束": {
    "必须包含：" [
      "使用城市名称作为标题{{CITY_NAME }} ",
      "严格的半身像（仅腰部以上）",
      "下半身完全裁剪",
      "Y2K风格的动态姿势，充满张力",
      "俏皮但克制的表情",
      "纸质拼贴和剪贴杂志风格",
      "与城市相关的背景和贴纸{{CITY_NAME }} ",
      "全宽杂志风格拼贴页脚",
      "可见的纸张纹理和层次感"
    ],
    "必须避免：" [
      "全身照",
      "可见的腿、膝盖、大腿或脚",
      "中性或僵硬的姿势",
      "过于可爱或幼稚的表情",
      "性化的表情或手势",
      "怪诞的面部扭曲",
      "极简主义或空白的布局",
      "光面数字或3D材质"
    ]
  },
  "negative_prompt": "全身，腿部可见，膝盖，大腿，脚，僵硬姿势，中立姿势，幼稚表情，夸张可爱表情，性化表情，模糊面部，畸形手，多余手指，解剖结构错误，怪诞扭曲，极简布局，平面图像，超写实摄影，光滑表面，塑料皮肤，暗淡色彩，水印，标志，无法辨认的文字",
  "typography_rules": {
    "标题": {
      "正文": " {{城市名称}} ",
      "字体": "粗体几何无衬线字体，大写",
      "处理方式": "每个字母位于单独的彩色纸矩形上，略微拱起，带有微妙的阴影",
      "材质": "印刷纸剪裁"
    },
    "辅助文本": {
      "风格": "杂志社论版块，趣味贴纸标题，对话气泡",
      "材质": "纸质印刷纹理"
    }
  },
  "渲染注释": {
    "depth_layers": "背景：城市纸张层->中景：半身人物->前景：动态姿势、表情丰富的面部、贴纸和文字。"print_feel": "强烈的杂志印刷纹理，
    带有半色调网点、纸张纹理和轻微的墨迹晕染。"edge_treatment": "清晰可见的不完美裁切纸张边缘。"
  }
}

